// Location Normalization & Deduplication Helpers
export const deduplicateLocationString = (locationStr: string | undefined | null): string => {
  if (!locationStr || typeof locationStr !== 'string') return '';
  const rawParts = locationStr.split(',').map((p) => p.trim()).filter(Boolean);
  const uniqueParts: string[] = [];
  const seen = new Set<string>();
  for (const part of rawParts) {
    const lower = part.toLowerCase();
    if (!seen.has(lower)) {
      seen.add(lower);
      uniqueParts.push(part);
    }
  }
  return uniqueParts.join(', ');
};

export const parseAndNormalizeLocation = (
  inputCity?: string,
  inputState?: string,
  inputCountry?: string,
  rawLocation?: string
): { city: string; state: string; country: string; location: string } => {
  const combined = [inputCity, inputState, inputCountry, rawLocation]
    .filter(Boolean)
    .join(', ');

  if (!combined.trim()) {
    return { city: '', state: '', country: '', location: '' };
  }

  const rawTokens = combined.split(',').map((t) => t.trim()).filter(Boolean);
  const uniqueTokens: string[] = [];
  const seen = new Set<string>();

  for (const token of rawTokens) {
    const lower = token.toLowerCase();
    if (!seen.has(lower)) {
      seen.add(lower);
      uniqueTokens.push(token);
    }
  }

  if (uniqueTokens.length === 0) {
    return { city: '', state: '', country: '', location: '' };
  }

  let cleanCity = '';
  let cleanState = '';
  let cleanCountry = '';

  if (uniqueTokens.length === 1) {
    cleanCity = uniqueTokens[0];
  } else if (uniqueTokens.length === 2) {
    cleanCity = uniqueTokens[0];
    cleanCountry = uniqueTokens[1];
  } else {
    cleanCity = uniqueTokens[0];
    cleanState = uniqueTokens[1];
    cleanCountry = uniqueTokens.slice(2).join(', ');
  }

  const cleanLocation = uniqueTokens.join(', ');

  return {
    city: cleanCity,
    state: cleanState,
    country: cleanCountry,
    location: cleanLocation
  };
};

