// Structured Personal Information Interface (Draft-based Editing Architecture)
export interface PersonalInfoData {
  firstName: string;
  lastName: string;
  name: string;
  headline: string;
  email: string;
  phone: string;
  city: string;
  state: string;
  country: string;
  location: string;
  photo?: string;
  socialLinks: SocialLinkItem[];
  linkedinUrl?: string;
  githubUrl?: string;
  portfolioUrl?: string;
}

export const extractPersonalInfo = (data?: ResumeBuilderData | null): PersonalInfoData => {
  if (!data) {
    return {
      firstName: '',
      lastName: '',
      name: '',
      headline: '',
      email: '',
      phone: '',
      city: '',
      state: '',
      country: '',
      location: '',
      photo: '',
      socialLinks: [],
      linkedinUrl: '',
      githubUrl: '',
      portfolioUrl: ''
    };
  }

  let first = (data.firstName || '').trim();
  let last = (data.lastName || '').trim();
  if (!first && !last && data.name && !isPlaceholderText(data.name)) {
    const parts = data.name.trim().split(/\s+/);
    first = parts[0] || '';
    last = parts.slice(1).join(' ') || '';
  }

  const normLoc = parseAndNormalizeLocation(data.city, data.state, data.country, data.location);

  return {
    firstName: isPlaceholderText(first) ? '' : first,
    lastName: isPlaceholderText(last) ? '' : last,
    name: isPlaceholderText(data.name) ? '' : (data.name || ''),
    headline: isPlaceholderText(data.headline) ? '' : (data.headline || ''),
    email: isPlaceholderText(data.email) ? '' : (data.email || ''),
    phone: isPlaceholderText(data.phone) ? '' : (data.phone || ''),
    city: isPlaceholderText(normLoc.city) ? '' : normLoc.city,
    state: isPlaceholderText(normLoc.state) ? '' : normLoc.state,
    country: isPlaceholderText(normLoc.country) ? '' : normLoc.country,
    location: isPlaceholderText(normLoc.location) ? '' : normLoc.location,
    photo: data.photo || '',
    socialLinks: Array.isArray(data.socialLinks)
      ? data.socialLinks.map((l) => ({ ...l }))
      : [],
    linkedinUrl: data.linkedinUrl || '',
    githubUrl: data.githubUrl || '',
    portfolioUrl: data.portfolioUrl || ''
  };
};

