        skills: ['Software Engineer', 'Distributed Systems', 'Java', 'Spring Boot', 'REST APIs', 'Microservices', 'SQL', 'Git'],
        educationRequired: "Bachelor's degree in Computer Science, or related field of study.",
        deadline: '2026-10-31',
