  const handleSavePersonalInfo = async () => {
    if (!resumeData) return;

    // Validation
    const errors: Record<string, string> = {};

    const currentFirst = (draftPersonalInfo.firstName || '').trim();
    const currentLast = (draftPersonalInfo.lastName || '').trim();
    const currentEmail = (draftPersonalInfo.email || '').trim();
    const currentPhone = (draftPersonalInfo.phone || '').trim();

    if (!currentFirst && !draftPersonalInfo.name?.trim()) {
      errors.firstName = 'First name is required.';
    }

    if (!currentLast && !draftPersonalInfo.name?.trim()) {
      errors.lastName = 'Last name is required.';
    }

    if (!currentEmail) {
      errors.email = 'Email is required.';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(currentEmail)) {
      errors.email = 'Please enter a valid email address.';
    }

    if (!currentPhone) {
      errors.phone = 'Phone number is required.';
    } else if (currentPhone.replace(/[^0-9+]/g, '').length < 6) {
      errors.phone = 'Please enter a valid phone number.';
    }

    // Validate social links URLs if entered
    if (draftPersonalInfo.socialLinks) {
      for (const link of draftPersonalInfo.socialLinks) {
        if (link.url && link.url.trim()) {
          const trimmed = link.url.trim();
          if (!trimmed.includes('.') && !trimmed.startsWith('http://') && !trimmed.startsWith('https://')) {
            errors[`link-${link.id}`] = 'Please enter a valid URL.';
          }
        }
      }
    }

    if (Object.keys(errors).length > 0) {
      setFormErrors(errors);
      showToast({
        type: 'error',
        title: 'Validation Error',
        message: Object.values(errors)[0]
      });
      return;
    }

    setFormErrors({});
    setIsSaving(true);
    setSaveStatus('saving');

    try {
      const derivedName = `${currentFirst} ${currentLast}`.trim() || draftPersonalInfo.name || '';
      const normLoc = parseAndNormalizeLocation(
        draftPersonalInfo.city,
        draftPersonalInfo.state,
        draftPersonalInfo.country,
        draftPersonalInfo.location
      );

      const committedInfo: PersonalInfoData = {
        ...draftPersonalInfo,
        firstName: currentFirst,
        lastName: currentLast,
        name: derivedName,
        city: normLoc.city,
        state: normLoc.state,
        country: normLoc.country,
        location: normLoc.location
      };

      const updated: ResumeBuilderData = {
        ...resumeData,
        ...committedInfo
      };

      // Update saved state
      setSavedPersonalInfo(committedInfo);

      // Record update in undo/redo history and update resumeData (preview updates)
      handleUpdate(() => updated);

      if (id) {
        await candidateService.updateResume(id, {
          resumeData: JSON.stringify(updated)
        });
      }

      setSaveStatus('saved');
      showToast({
        type: 'success',
        title: 'Saved Successfully',
        message: 'Personal Information saved and updated.'
      });
      setIsEditingPersonalInfo(false);
    } catch (err: any) {
      console.error('Failed to sync personal info:', err);
      setSaveStatus('error');
      showToast({
        type: 'error',
        title: 'Sync Error',
        message: 'Unable to save your changes. Please try again.'
      });
    } finally {
      setIsSaving(false);
    }
  };

