  const normalizeSkillsToString = (val: any): string => {
    if (typeof val === 'string') return val;
    if (Array.isArray(val)) return val.filter(Boolean).map(String).join(', ');
    return '';
  };

  // Helper functions for skill lists
  const parseSkillsList = (skillsStr: any): string[] => {
    if (!skillsStr) return [];
    if (Array.isArray(skillsStr)) return skillsStr.filter(Boolean).map(String);
    if (typeof skillsStr === 'string') {
      return skillsStr
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean);
    }
    return [];
  };

  const hasSkill = (skillsStr: any, skillName: string): boolean => {
    const list = parseSkillsList(skillsStr);
    return list.some((s) => s.toLowerCase() === skillName.trim().toLowerCase());
  };

  const addSkillToCategory = (currentStr: any, newSkill: string): string => {
    const trimmed = newSkill.trim();
    const list = parseSkillsList(currentStr);
    if (!trimmed) return list.join(', ');
    if (list.some((s) => s.toLowerCase() === trimmed.toLowerCase())) {
      return list.join(', ');
    }
    return [...list, trimmed].join(', ');
  };

  const removeSkillFromCategory = (currentStr: any, skillToRemove: string): string => {
    const list = parseSkillsList(currentStr);
    return list.filter((s) => s.toLowerCase() !== skillToRemove.trim().toLowerCase()).join(', ');
  };

  const toggleSkillInCategory = (currentStr: any, skillName: string): string => {
    if (hasSkill(currentStr, skillName)) {
      return removeSkillFromCategory(currentStr, skillName);
    } else {
      return addSkillToCategory(currentStr, skillName);
    }
  };

  // Skills Handlers (Matching Screenshots 1, 2, 3, 4, 5)
  const handleStartEditSkills = (categoryKey?: string) => {
    if (!resumeData) return;
    setSkillsSnapshot(JSON.parse(JSON.stringify(resumeData.skills)));
    setEditingCategoryKey(categoryKey || null);
    setIsEditingSkills(true);
  };

  const handleCancelSkills = () => {
    if (skillsSnapshot && resumeData) {
      handleUpdate((prev) => ({ ...prev, skills: skillsSnapshot }));
    }
    setIsEditingSkills(false);
    setEditingCategoryKey(null);
  };

  const handleSaveSkills = () => {
    if (!resumeData) return;
    triggerAutoSave(resumeData, true);
    setIsEditingSkills(false);
    setEditingCategoryKey(null);
    showToast({
      type: 'success',
      title: 'Skills Saved',
      message: 'Skills updated successfully.'
    });
  };

  // ── Auto-Fill Sample Details for Skills & Competencies ──
  const handleAutoFillSampleSkills = () => {
    if (!resumeData) return;

    // Standard sample skills aligned with prompt requirements
    const sampleSkillsMap: Record<string, string[]> = {
      programmingLanguages: ['Java', 'Python', 'JavaScript', 'C', 'C++'],
      frameworksLibraries: ['Spring Boot', 'React', 'Hibernate', 'Node.js'],
      toolsPlatforms: ['Git', 'GitHub', 'Docker', 'VS Code'],
      databases: ['PostgreSQL', 'MySQL', 'MongoDB'],
      softSkills: ['Communication', 'Problem Solving', 'Teamwork'],
      languages: ['English', 'Hindi']
    };

    let addedCount = 0;
    const currentSkills = resumeData.skills || ({} as any);

    // Merge helper: preserves all existing candidate skills, filters out placeholder text,
    // and appends only non-duplicate sample entries
    const mergeCategorySkills = (existingVal: any, sampleList: string[]): string => {
      const rawList = parseSkillsList(existingVal);
      // Keep all non-placeholder candidate skills intact
      const existingSkills = rawList.filter((s) => !isPlaceholderText(s));
      const existingLowerSet = new Set(existingSkills.map((s) => s.toLowerCase().trim()));

      const newToAdd: string[] = [];
      for (const sample of sampleList) {
        const trimmed = sample.trim();
        if (trimmed && !existingLowerSet.has(trimmed.toLowerCase())) {
          newToAdd.push(trimmed);
          existingLowerSet.add(trimmed.toLowerCase());
          addedCount++;
        }
      }

      return [...existingSkills, ...newToAdd].join(', ');
    };

    const updatedSkills = {
      ...currentSkills,
      programmingLanguages: mergeCategorySkills(currentSkills.programmingLanguages, sampleSkillsMap.programmingLanguages),
      frameworksLibraries: mergeCategorySkills(currentSkills.frameworksLibraries, sampleSkillsMap.frameworksLibraries),
      toolsPlatforms: mergeCategorySkills(currentSkills.toolsPlatforms, sampleSkillsMap.toolsPlatforms),
      databases: mergeCategorySkills(currentSkills.databases, sampleSkillsMap.databases),
      softSkills: mergeCategorySkills(currentSkills.softSkills, sampleSkillsMap.softSkills),
      languages: mergeCategorySkills(currentSkills.languages, sampleSkillsMap.languages),
      // Preserve any existing custom categories completely
      customCategories: currentSkills.customCategories || []
    };

    // Update in-memory state immediately so the editor displays the new chips
    handleUpdate((prev) => ({
      ...prev,
      skills: updatedSkills
    }));

    showToast({
      type: 'info',
      title: 'Sample Skills Auto-Filled',
      message: addedCount > 0
        ? `Merged ${addedCount} sample skill${addedCount === 1 ? '' : 's'} across categories. Please review before saving.`
        : 'All sample skills are already present in your skills categories.'
    });
  };

  const handleToggleSkill = (categoryKey: string, skillName: string) => {
    handleUpdate((prev) => {
      // Check if standard category
      if (categoryKey in prev.skills) {
        const current = (prev.skills as any)[categoryKey] || '';
        const updated = toggleSkillInCategory(current, skillName);
        return {
          ...prev,
          skills: {
            ...prev.skills,
            [categoryKey]: updated
          }
        };
      } else {
        // Custom category
        const customCategories = (prev.skills.customCategories || []).map((cat) => {
          if (cat.id === categoryKey || cat.name === categoryKey) {
            return {
              ...cat,
              skills: toggleSkillInCategory(cat.skills, skillName)
            };
          }
          return cat;
        });
        return {
          ...prev,
          skills: {
            ...prev.skills,
            customCategories
          }
        };
      }
    });
  };

  const handleAddKeywordSkill = (categoryKey: string) => {
    const inputVal = categoryKeywordInputs[categoryKey]?.trim();
    if (!inputVal) return;

    handleUpdate((prev) => {
      if (categoryKey in prev.skills) {
        const current = (prev.skills as any)[categoryKey] || '';
        const updated = addSkillToCategory(current, inputVal);
        return {
          ...prev,
          skills: {
            ...prev.skills,
            [categoryKey]: updated
          }
        };
      } else {
        const customCategories = (prev.skills.customCategories || []).map((cat) => {
          if (cat.id === categoryKey || cat.name === categoryKey) {
            return {
              ...cat,
              skills: addSkillToCategory(cat.skills, inputVal)
            };
          }
          return cat;
        });
        return {
          ...prev,
          skills: {
            ...prev.skills,
            customCategories
          }
        };
      }
    });

    setCategoryKeywordInputs((prev) => ({ ...prev, [categoryKey]: '' }));
  };

  const handleRemoveSkill = (categoryKey: string, skillName: string) => {
    handleUpdate((prev) => {
      if (categoryKey in prev.skills) {
        const current = (prev.skills as any)[categoryKey] || '';
        const updated = removeSkillFromCategory(current, skillName);
        return {
          ...prev,
          skills: {
            ...prev.skills,
            [categoryKey]: updated
          }
        };
      } else {
        const customCategories = (prev.skills.customCategories || []).map((cat) => {
          if (cat.id === categoryKey || cat.name === categoryKey) {
            return {
              ...cat,
              skills: removeSkillFromCategory(cat.skills, skillName)
            };
          }
          return cat;
        });
        return {
          ...prev,
          skills: {
            ...prev.skills,
            customCategories
          }
        };
      }
    });
  };

  const handleCreateCategory = () => {
    const name = newCategoryName.trim();
    if (!name) return;

    // Check if it matches a standard category name
    const matchedStd = DEFAULT_SKILL_CATEGORIES.find(
      (c) => c.name.toLowerCase() === name.toLowerCase()
    );

    if (matchedStd) {
      // Already exists in standard categories
      setEditingCategoryKey(matchedStd.key);
      setNewCategoryName('');
      showToast({
        type: 'info',
        title: 'Category Exists',
        message: `Focused on ${matchedStd.name}.`
      });
      return;
    }

    const newId = `cat-${Date.now()}`;
    handleUpdate((prev) => {
      const existing = prev.skills.customCategories || [];
      if (existing.some((c) => c.name.toLowerCase() === name.toLowerCase())) {
        return prev;
      }
      return {
        ...prev,
        skills: {
          ...prev.skills,
          customCategories: [...existing, { id: newId, name, skills: '' }]
        }
      };
    });

    setNewCategoryName('');
    showToast({
      type: 'success',
      title: 'Skill Category Added',
      message: `Created category "${name}".`
    });
  };

  const handleDeleteCategory = (categoryKey: string) => {
    handleUpdate((prev) => {
      if (categoryKey in prev.skills) {
        return {
          ...prev,
          skills: {
            ...prev.skills,
            [categoryKey]: ''
          }
        };
      } else {
        return {
          ...prev,
          skills: {
            ...prev.skills,
            customCategories: (prev.skills.customCategories || []).filter(
              (c) => c.id !== categoryKey && c.name !== categoryKey
            )
          }
        };
      }
    });
    showToast({
      type: 'info',
      title: 'Category Cleared',
      message: 'Category skills cleared.'
    });
  };

  const handleUpdate = (updater: (prev: ResumeBuilderData) => ResumeBuilderData) => {
    setResumeData((prev) => {
      if (!prev) return prev;
      const next = updater(prev);

      // Record snapshot into past stack if not currently executing undo/redo
      if (!isHistoryNavigatingRef.current) {
        const prevJson = JSON.stringify(prev);
        const nextJson = JSON.stringify(next);
        if (prevJson !== nextJson) {
          setPast((p) => {
            const trimmed = p.length >= 50 ? p.slice(p.length - 49) : p;
            return [...trimmed, JSON.parse(prevJson)];
          });
          // New change clears future redo stack
          setFuture([]);
        }
      }

      triggerAutoSave(next);
      return next;
    });
  };

  // Undo / Redo Actions (Parts 2-6: Synchronized with ATS Scoring & Preview)
  const handleUndo = () => {
    if (past.length === 0 || !resumeData) return;

    const previousState = past[past.length - 1];
    const newPast = past.slice(0, past.length - 1);
    const currentSnapshot = JSON.parse(JSON.stringify(resumeData));

    isHistoryNavigatingRef.current = true;
    setPast(newPast);
    setFuture((prevFuture) => [currentSnapshot, ...prevFuture]);
    setResumeData(previousState);
    triggerAutoSave(previousState);

    const pi = extractPersonalInfo(previousState);
    setSavedPersonalInfo(pi);
    if (!isEditingPersonalInfo) {
      setDraftPersonalInfo(pi);
    }

    setTimeout(() => {
      isHistoryNavigatingRef.current = false;
    }, 50);

    showToast({
      type: 'info',
      title: 'Undo',
      message: 'Restored previous resume state.'
    });
  };

  const handleRedo = () => {
    if (future.length === 0 || !resumeData) return;

    const nextState = future[0];
    const newFuture = future.slice(1);
    const currentSnapshot = JSON.parse(JSON.stringify(resumeData));

    isHistoryNavigatingRef.current = true;
    setFuture(newFuture);
    setPast((prevPast) => {
      const trimmed = prevPast.length >= 50 ? prevPast.slice(prevPast.length - 49) : prevPast;
      return [...trimmed, currentSnapshot];
    });
    setResumeData(nextState);
    triggerAutoSave(nextState);

    const pi = extractPersonalInfo(nextState);
    setSavedPersonalInfo(pi);
    if (!isEditingPersonalInfo) {
      setDraftPersonalInfo(pi);
    }

    setTimeout(() => {
      isHistoryNavigatingRef.current = false;
    }, 50);

    showToast({
      type: 'info',
      title: 'Redo',
      message: 'Reapplied undone resume state.'
    });
  };

  // Title Rename Handler
  const handleSaveTitle = async () => {
    setIsEditingTitle(false);
    if (!id || !titleInput.trim()) return;
    try {
      const updated = await candidateService.updateResume(id, {
        fileName: titleInput.trim()
      });
      setResume((prev) => (prev ? { ...prev, fileName: updated.fileName } : null));
      showToast({ type: 'success', title: 'Renamed', message: 'Resume name updated.' });
    } catch {
      showToast({ type: 'error', title: 'Error', message: 'Failed to rename resume.' });
    }
  };

  // Section Toggle (for Add Section Modal)
  const toggleSection = (sectionId: SectionId) => {
    handleUpdate((prev) => {
      const exists = prev.activeSections.includes(sectionId);
      return {
        ...prev,
        activeSections: exists
          ? prev.activeSections.filter((s) => s !== sectionId)
          : [...prev.activeSections, sectionId]
      };
    });
  };

  // Expand / Collapse Section Accordions
  const toggleAccordion = (key: string) => {
    setExpandedSections((prev) => ({
      ...prev,
      [key]: !prev[key]
    }));
  };


  const handleSelectTemplate = (templateId: 'low' | 'medium' | 'bulky') => {
    if (id) {
      try {
        localStorage.setItem(`resume_template_${id}`, templateId);
      } catch (e) {}
    }
    handleUpdate((prev) => {
      const next = { ...prev, template: templateId };
      if (id) {
        candidateService.updateResume(id, {
          resumeData: JSON.stringify(next)
        }).catch((err) => console.error('Failed to immediately persist template:', err));
      }
      return next;
    });
    showToast({
      type: 'success',
      title: 'Template Selected',
      message: `Switched to ${templateId.charAt(0).toUpperCase() + templateId.slice(1)} Template.`
    });
  };

  const resetToDefaultLayout = () => {
    applyLayoutPreset('balanced');
    handleSelectTemplate('medium');
    showToast({ type: 'info', title: 'Reset', message: 'Restored default styling.' });
  };

  // Dynamic ATS Score Calculation
  // ── ATS Suggestion Engine ──────────────────────────────────────────────────
  // Evaluates genuine resume sections & real content against ATS requirements.
  interface ATSSuggestion {
    id: string;
    category: string;
    severity: 'error' | 'warning' | 'info';
    title: string;
    pendingTitle?: string;
    completedTitle?: string;
    completedDescription?: string;
    reason: string;
    weight: number; // impact on score
    passing: boolean;
    navigateTo?: string; // jump to section
    detailedReason?: string;
    recruiterImpact?: string;
    proTip?: string;
    currentValue?: string;
    expectedValue?: string;
    suggestedCorrection?: string;
  }

  const getATSSuggestions = (): ATSSuggestion[] => {
    if (!resumeData) return [];
    const suggestions: ATSSuggestion[] = [];

    const isPlaceholder = (val: string | undefined | null) => {
      if (!val) return true;
      const trimmed = val.trim();
      if (!trimmed) return true;
      if (/^\[.*\]$/.test(trimmed)) return true;
      if (/^<.*>$/.test(trimmed)) return true;
      const lower = trimmed.toLowerCase();
      return lower === 'first name last name' ||
        lower === 'first name' ||
        lower === 'last name' ||
        lower === 'email@mit.edu' ||
        lower === 'skill here' ||
        lower === 'skill name' ||
        lower === 'insert skill' ||
        lower === 'institution name' ||
        lower === 'degree' ||
        lower === 'job title' ||
        lower === 'organization name' ||
        lower === 'project name' ||
        lower.includes('summarize your career') ||
        lower.includes('add description') ||
        lower.includes('mention your') ||
        lower.includes('mention project') ||
        lower.includes('mention education') ||
        lower.includes('add programming') ||
        lower.includes('add frameworks') ||
        lower.includes('add tools') ||
        lower.includes('add databases') ||
        lower.includes('add skills') ||
        lower.includes('list 3-5');
    };

    // ── 1. Contact Details (15 pts) ──
    const hasRealName = (!isPlaceholder(resumeData.firstName) && !isPlaceholder(resumeData.lastName)) ||
      (!isPlaceholder(resumeData.name) && (resumeData.name || '').trim().split(/\s+/).length >= 2);
    const hasRealPhone = !isPlaceholder(resumeData.phone) && (resumeData.phone || '').replace(/[^0-9]/g, '').length >= 7;
    const hasRealEmail = !isPlaceholder(resumeData.email) && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test((resumeData.email || '').trim());
    const hasRealLocation = (!isPlaceholder(resumeData.city) && (resumeData.city || '').trim().length > 0) ||
      (!isPlaceholder(resumeData.location) && (resumeData.location || '').trim().length > 0);
    const contactPassing = hasRealName && hasRealPhone && hasRealEmail && hasRealLocation;

    const missingContactParts: string[] = [];
    if (!hasRealName) missingContactParts.push('full name');
    if (!hasRealEmail) missingContactParts.push('valid email');
    if (!hasRealPhone) missingContactParts.push('phone number');
    if (!hasRealLocation) missingContactParts.push('location');

    const contactCurrentVal = missingContactParts.length === 0
      ? 'Full contact info provided'
      : `Missing: ${missingContactParts.join(', ')}`;
    const contactReason = missingContactParts.length === 0
      ? 'Verified: Full contact info (name, email, phone, location) is complete.'
      : (missingContactParts.length === 4
        ? 'Add your full name, phone number, email address, and location.'
        : `Add your missing ${missingContactParts.join(', ')} to ensure recruiters can reach you.`);

    suggestions.push({
      id: 'contact-essential',
      category: 'Contact Info',
      severity: 'error',
      pendingTitle: 'Essential Contact Details Missing',
      completedTitle: 'Essential Contact Details Verified',
      title: contactPassing ? 'Essential Contact Details Verified' : 'Essential Contact Details Missing',
      reason: contactReason,
      completedDescription: 'Verified: Full contact info (name, email, phone, location) is complete.',
      weight: 15,
      passing: contactPassing,
      navigateTo: 'personal-info',
      detailedReason: 'Incomplete or placeholder contact info prevents recruiters from reaching out for interview invitations and causes parsing rejections.',
      recruiterImpact: 'Candidates without clear location and direct contact information are skipped by recruiters.',
      proTip: 'Use a professional email (first.last@domain.com) and include city/state for location-based search filtering.',
      currentValue: contactCurrentVal,
      expectedValue: 'Full Name, Email, Phone Number, Location',
      suggestedCorrection: 'Fill in all required fields in the Personal Information section.'
    });

    // ── 2. Professional Summary (10 pts) ──
    const summaryText = resumeData.summary || (resumeData as any).bio || '';
    const hasSummary = !isPlaceholder(summaryText);
    const summaryValid = hasSummary && summaryText.trim().length >= 40;
    const summaryCurrentVal = !hasSummary
      ? 'No summary provided'
      : (summaryValid ? `Comprehensive summary (${summaryText.trim().length} chars)` : `Brief summary (${summaryText.trim().length}/40 chars)`);
    const summaryTitle = !hasSummary ? 'Missing Professional Summary' : (summaryValid ? 'Professional Summary Provided' : 'Expand Professional Summary');
    const summaryReason = !hasSummary
      ? 'Write a 2-3 sentence career summary highlighting your core expertise and value.'
      : (summaryValid
        ? 'Verified: Career summary is present and highlights core competencies.'
        : 'Your summary is too brief. Expand it to 2-3 sentences (minimum 40 characters) highlighting your primary technical domain.');

    suggestions.push({
      id: 'summary-genuine',
      category: 'Summary',
      severity: 'warning',
      pendingTitle: summaryTitle,
      completedTitle: 'Professional Summary Provided',
      title: summaryValid ? 'Professional Summary Provided' : summaryTitle,
      reason: summaryReason,
      completedDescription: 'Verified: Career summary is present and highlights core competencies.',
      weight: 10,
      passing: summaryValid,
      navigateTo: 'summary',
      detailedReason: 'The summary is indexed heavily for high-level keyword clusters and target job titles within the initial 50-70 words of the resume.',
      recruiterImpact: 'Provides an immediate snapshot of your career identity and senior alignment.',
      proTip: 'Summarize your years of experience, primary domain, and top 2 career achievements.',
      currentValue: summaryCurrentVal,
      expectedValue: '2-3 sentences (minimum 40 characters)',
      suggestedCorrection: 'Craft a concise summary highlighting your domain skills and impact.'
    });

    // ── 3. Education Credentials (15 pts) ──
    const rawEduList = resumeData.education || [];
    const hasRawEducation = rawEduList.length > 0;
    const genuineEdu = rawEduList.filter(e =>
      !isPlaceholder(e.institution) && !isPlaceholder(e.degree)
    );
    const hasEducationSection = genuineEdu.length >= 1;
    const eduTitle = hasEducationSection ? 'Academic Education Verified' : (hasRawEducation ? 'Education Entry Incomplete' : 'Missing Education Section & Credentials');
    const eduReason = hasEducationSection
      ? 'Verified: Institution and degree credentials are confirmed.'
      : (hasRawEducation
        ? 'Update your education entry to include both your Institution Name and Degree.'
        : 'Add your degree, institution name, and graduation timeline.');
    const eduCurrentVal = hasEducationSection ? `${genuineEdu.length} verified qualification(s)` : (hasRawEducation ? 'Incomplete degree or institution' : '0 education entries');

    suggestions.push({
      id: 'section-education',
      category: 'Education',
      severity: 'error',
      pendingTitle: eduTitle,
      completedTitle: 'Academic Education Verified',
      title: hasEducationSection ? 'Academic Education Verified' : eduTitle,
      reason: eduReason,
      completedDescription: 'Verified: Institution and degree credentials are confirmed.',
      weight: 15,
      passing: hasEducationSection,
      navigateTo: 'education',
      detailedReason: 'Many enterprise organizations enforce strict minimum degree requirements in ATS screening.',
      recruiterImpact: 'Verifies educational pedigree, graduation timeline, and relevant academic background.',
      proTip: 'Include institution name, degree obtained, graduation year, and GPA/CGPA if applicable.',
      currentValue: eduCurrentVal,
      expectedValue: 'At least 1 institution and degree entry',
      suggestedCorrection: 'Add your formal degree, university or college name, and graduation timeline.'
    });

    // ── 4. Skills & Competencies (20 pts - Hierarchical Dependency) ──
    const allSkillsList: string[] = [];
    if (resumeData.skills) {
      Object.entries(resumeData.skills).forEach(([key, val]) => {
        if (key === 'customCategories' && Array.isArray(val)) {
          val.forEach((cc: any) => {
            if (cc && typeof cc.skills === 'string') {
              cc.skills.split(/[,\n]+/).forEach((s: string) => {
                const trimmed = s.trim();
                if (trimmed && !isPlaceholder(trimmed)) allSkillsList.push(trimmed);
              });
            }
          });
        } else if (typeof val === 'string' && val.trim()) {
          val.split(/[,\n]+/).forEach(s => {
            const trimmed = s.trim();
            if (trimmed && !isPlaceholder(trimmed)) allSkillsList.push(trimmed);
          });
        }
      });
    }

    const skillCount = allSkillsList.length;
    if (skillCount === 0) {
      // Primary blocker only (20 pts)
      suggestions.push({
        id: 'section-skills',
        category: 'Skills',
        severity: 'error',
        pendingTitle: 'Missing Skills Section & Competencies',
        completedTitle: 'Skills Section & Competencies Added',
        title: 'Missing Skills Section & Competencies',
        reason: 'Add a dedicated Skills section containing your core technical tools and capabilities.',
        completedDescription: 'Verified: Core technical and industry skills are included in your resume.',
        weight: 20,
        passing: false,
        navigateTo: 'skills',
        detailedReason: 'A dedicated Skills section allows ATS keyword matchers to index your exact competencies and verify alignment with the job description keywords.',
        recruiterImpact: 'Allows recruiters to instantly confirm whether you satisfy required prerequisites and technical stack demands.',
        proTip: 'Group skills by clear categories (e.g., Programming Languages, Frameworks, Tools) to improve human and algorithmic readability.',
        currentValue: '0 skills listed',
        expectedValue: 'Dedicated skills section with core competencies',
        suggestedCorrection: 'Open the Skills section and add your key technical languages, frameworks, and tools.'
      });
    } else {
      // Primary presence passes (10 pts)
      suggestions.push({
        id: 'section-skills',
        category: 'Skills',
        severity: 'error',
        pendingTitle: 'Missing Skills Section & Competencies',
        completedTitle: 'Skills Section & Competencies Added',
        title: 'Skills Section & Competencies Added',
        reason: 'Add a dedicated Skills section containing your core technical tools and capabilities.',
        completedDescription: `Verified: Core technical and industry skills are included in your resume (${skillCount} listed).`,
        weight: 10,
        passing: true,
        navigateTo: 'skills',
        detailedReason: 'A dedicated Skills section allows ATS keyword matchers to index your exact competencies and verify alignment with the job description keywords.',
        recruiterImpact: 'Allows recruiters to instantly confirm whether you satisfy required prerequisites and technical stack demands.',
        proTip: 'Group skills by clear categories (e.g., Programming Languages, Frameworks, Tools) to improve human and algorithmic readability.',
        currentValue: `${skillCount} skills listed`,
        expectedValue: 'Core technical skills section',
        suggestedCorrection: 'Maintain structured categorization for ATS parsers.'
      });

      // Secondary density check (10 pts)
      const skillsCountPassing = skillCount >= 5;
      suggestions.push({
        id: 'skills-count',
        category: 'Skills',
        severity: skillsCountPassing ? 'info' : 'warning',
        pendingTitle: 'Insufficient Skill Count',
        completedTitle: 'Sufficient Core Skills Count (>= 5 skills)',
        title: skillsCountPassing ? 'Sufficient Core Skills Count (>= 5 skills)' : 'Insufficient Skill Count',
        reason: `Expand your Skills section by adding more relevant technologies or tools (currently: ${skillCount}/5, min: 5).`,
        completedDescription: `Verified: Meets recommended keyword density with ${skillCount} core skills.`,
        weight: 10,
        passing: skillsCountPassing,
        navigateTo: 'skills',
        detailedReason: 'ATS algorithms calculate keyword match density. Profiles with under 5 core skills rarely hit the 70% threshold required for recruiter review.',
        recruiterImpact: 'Recruiters use skill search filters to narrow applicant pools from hundreds to top contenders.',
        proTip: 'Include both core hard skills (languages, frameworks) and pertinent domain tools.',
        currentValue: `${skillCount} skills listed`,
        expectedValue: '5 or more relevant skills',
        suggestedCorrection: 'Add additional technical tools, frameworks, and programming languages you have worked with.'
      });
    }

    // ── 5. Practical Experience & Projects (30 pts) - Intelligent Fresher Fairness ──
    const genuineExp = (resumeData.experience || []).filter(e =>
      !isPlaceholder(e.company) && !isPlaceholder(e.role)
    );
    const genuineProjects = (resumeData.projects || []).filter(p =>
      !isPlaceholder(p.title) && (!isPlaceholder(p.description) || !isPlaceholder(p.technologies))
    );
    const expHasDescriptions = genuineExp.some(e =>
      !isPlaceholder(e.description) && (e.description || '').trim().length >= 40
    );
    const projHasDescriptions = genuineProjects.some(p =>
      (!isPlaceholder(p.description) && (p.description || '').trim().length >= 30) ||
      (!isPlaceholder(p.technologies) && (p.technologies || '').trim().length >= 3)
    );

    if (genuineExp.length >= 1) {
      // Profile 1: Experienced Candidate
      suggestions.push({
        id: 'section-experience',
        category: 'Work Experience',
        severity: 'error',
        pendingTitle: 'Missing Work Experience',
        completedTitle: 'Professional Work Experience Documented',
        title: 'Professional Work Experience Documented',
        reason: 'Add your employment history, job title, company, and timeline.',
        completedDescription: `Verified: Professional work experience is documented (${genuineExp.length} role(s)).`,
        weight: 15,
        passing: true,
        navigateTo: 'experience',
        detailedReason: 'ATS algorithms look for structured work experience to gauge hands-on technical background.',
        recruiterImpact: 'Recruiters spend 80% of their initial scan evaluating career progression.',
        proTip: 'Ensure entries are in reverse chronological order with measurable bullet points.',
        currentValue: `${genuineExp.length} role(s) documented`,
        expectedValue: 'At least 1 professional work experience entry',
        suggestedCorrection: 'Keep your roles updated with current title and organization.'
      });

      suggestions.push({
        id: 'exp-descriptions-genuine',
        category: 'Work Experience',
        severity: expHasDescriptions ? 'info' : 'warning',
        pendingTitle: 'Detailed Experience Bullet Points',
        completedTitle: 'Detailed Experience Bullet Points Included',
        title: expHasDescriptions ? 'Detailed Experience Bullet Points Included' : 'Detailed Experience Bullet Points',
        reason: 'Add comprehensive bullet points describing responsibilities and accomplishments (minimum 40 characters).',
        completedDescription: 'Verified: Roles contain comprehensive accomplishment bullet points.',
        weight: 15,
        passing: expHasDescriptions,
        navigateTo: 'experience',
        detailedReason: 'Bullet descriptions provide contextual keywords ATS systems score against requirements.',
        recruiterImpact: 'Recruiters want to see specific contributions rather than generic job duties.',
        proTip: 'Frame bullet points with the XYZ formula: Accomplished [X] as measured by [Y], by doing [Z].',
        currentValue: expHasDescriptions ? 'Detailed bullet points provided' : 'Bullet points too brief or missing',
        expectedValue: 'Action-driven bullet points (>= 40 characters)',
        suggestedCorrection: 'Elaborate on your day-to-day contributions, technologies used, and outcomes delivered.'
      });
    } else if (genuineProjects.length >= 1) {
      // Profile 2: Fresher / Student Candidate (NO PENALTY FOR LACKING WORK EXPERIENCE!)
      suggestions.push({
        id: 'section-projects',
        category: 'Projects',
        severity: 'error',
        pendingTitle: 'Missing Projects Section',
        completedTitle: 'Projects & Deliverables Documented',
        title: 'Projects & Deliverables Documented',
        reason: 'Add academic, capstone, or personal technical projects highlighting your hands-on coding ability.',
        completedDescription: `Verified: Practical project deliverables documented (${genuineProjects.length} listed).`,
        weight: 15,
        passing: true,
        navigateTo: 'projects',
        detailedReason: 'For freshers and early-career candidates, projects serve as primary proof of technical competence.',
        recruiterImpact: 'Recruiters evaluate problem solving, architecture choices, and stack familiarity through project work.',
        proTip: 'Highlight technologies used, role, and provide links or measurable metrics.',
        currentValue: `${genuineProjects.length} project(s) documented`,
        expectedValue: 'At least 1 technical or academic project',
        suggestedCorrection: 'Keep project documentation clear with architecture and repository links.'
      });

      suggestions.push({
        id: 'proj-descriptions-genuine',
        category: 'Projects',
        severity: projHasDescriptions ? 'info' : 'warning',
        pendingTitle: 'Detailed Project Descriptions & Tech Stack',
        completedTitle: 'Hands-on Project Portfolio Verified (Fresher Credit)',
        title: projHasDescriptions ? 'Hands-on Project Portfolio Verified (Fresher Credit)' : 'Detailed Project Descriptions & Tech Stack',
        reason: 'Add comprehensive descriptions and technologies used to showcase your hands-on technical depth.',
        completedDescription: 'Verified: Practical project portfolio demonstrates strong hands-on capabilities in lieu of corporate tenure.',
        weight: 15,
        passing: projHasDescriptions,
        navigateTo: 'projects',
        detailedReason: 'Early-career ATS models weight robust academic projects equivalently to entry-level internships.',
        recruiterImpact: 'Demonstrates initiative, end-to-end delivery, and code craftsmanship.',
        proTip: 'Include architecture overview, stack details, and GitHub links.',
        currentValue: projHasDescriptions ? 'Technical deliverables and tech stack described' : 'Project description or tech stack missing',
        expectedValue: 'Detailed project description and technologies used',
        suggestedCorrection: 'Describe the technical challenge solved, technologies used, and system outcomes.'
      });
    } else {
      // Profile 3: Completely empty practical experience (0 exp and 0 projects)
      suggestions.push({
        id: 'section-practical-exp',
        category: 'Practical Experience',
        severity: 'error',
        pendingTitle: 'Missing Practical Experience (Projects or Work Experience)',
        completedTitle: 'Practical Experience Documented',
        title: 'Missing Practical Experience (Projects or Work Experience)',
        reason: 'Add at least one technical project, internship, or professional role demonstrating your practical capabilities.',
        completedDescription: 'Verified: Practical experience or technical projects are documented.',
        weight: 30,
        passing: false,
        navigateTo: 'projects',
        detailedReason: 'ATS algorithms and recruiters require evidence of applied hands-on capabilities through projects or employment.',
        recruiterImpact: 'Early-career candidates can satisfy this requirement with robust academic projects, while experienced candidates use work history.',
        proTip: 'Add an academic capstone, personal coding project, internship, or professional role.',
        currentValue: '0 projects and 0 work experience entries',
        expectedValue: 'At least 1 technical project or work experience entry',
        suggestedCorrection: 'Click Fix to add a technical project or work experience entry.'
      });
    }

    // ── 6. Content Quality & Impact (10 pts) - ONLY evaluated when descriptions exist! ──
    const allDescriptions = [
      ...genuineExp.map(e => e.description || ''),
      ...genuineProjects.map(p => p.description || '')
    ].join(' ').trim();
    const hasAnyDescriptions = allDescriptions.length >= 30;

    if (hasAnyDescriptions) {
      const hasMetrics = /\b\d+(\.\d+)?%|\$\d+|\b\d+\+?\s*(users|clients|requests|ms|hours|days|x|fold|k|m|million|billion)\b/i.test(allDescriptions);
      suggestions.push({
        id: 'quantifiable-metrics',
        category: 'Content Quality',
        severity: 'info',
        pendingTitle: 'Quantifiable Metrics & Measurable Impact',
        completedTitle: 'Quantifiable Metrics & Impact Demonstrated',
        title: hasMetrics ? 'Quantifiable Metrics & Impact Demonstrated' : 'Quantifiable Metrics & Measurable Impact',
        reason: 'Include numbers, percentages, or growth metrics to prove tangible impact.',
        completedDescription: 'Verified: Measurable metrics and percentages found in project or work descriptions.',
        weight: 5,
        passing: hasMetrics,
        navigateTo: genuineExp.length >= 1 ? 'experience' : 'projects',
        detailedReason: 'Resumes with measurable results score higher in AI-driven semantic ranking algorithms.',
        recruiterImpact: 'Numbers give hiring managers confidence in your scale of impact and competency.',
        proTip: 'Add stats such as "Reduced load time by 35%" or "Managed a team of 6 engineers".',
        currentValue: hasMetrics ? 'Quantifiable metrics detected' : 'No measurable metrics found',
        expectedValue: 'Quantifiable metrics or numbers in descriptions',
        suggestedCorrection: 'Include specific numbers, percentages, user counts, or performance gains in your descriptions.'
      });

      const hasActionVerbs = /\b(Led|Developed|Designed|Engineered|Spearheaded|Architected|Implemented|Automated|Optimized|Constructed|Orchestrated|Transformed|Built|Created|Delivered|Collaborated|Formulated)\b/i.test(allDescriptions);
      suggestions.push({
        id: 'action-verbs',
        category: 'Content Quality',
        severity: 'info',
        pendingTitle: 'Strong Action Verbs in Bullet Points',
        completedTitle: 'Strong Action Verbs Applied',
        title: hasActionVerbs ? 'Strong Action Verbs Applied' : 'Strong Action Verbs in Bullet Points',
        reason: 'Start bullet points with impactful verbs like Engineered, Spearheaded, or Optimized.',
        completedDescription: 'Verified: Strong leadership and technical action verbs detected in descriptions.',
        weight: 5,
        passing: hasActionVerbs,
        navigateTo: genuineExp.length >= 1 ? 'experience' : 'projects',
        detailedReason: 'Action verbs signal leadership, ownership, and initiative to natural language parsers.',
        recruiterImpact: 'Creates an active, compelling narrative that holds recruiter interest.',
        proTip: 'Avoid passive voice ("Responsible for...") and replace with decisive action verbs.',
        currentValue: hasActionVerbs ? 'Strong action verbs detected' : 'No strong action verbs found',
        expectedValue: 'Active verbs (e.g., Engineered, Spearheaded, Developed)',
        suggestedCorrection: 'Begin each bullet point with a decisive active verb describing your engineering action.'
      });
    }

    return suggestions;
  };

  const checkResumeReadiness = () => {
    if (!resumeData) return { isReady: false, score: 0, hasCriticalBlockers: true };
    const allSuggestions = getATSSuggestions();
    const pendingSuggestions = allSuggestions.filter(
      s => !s.passing && !deletedSuggestionIds.has(s.id)
    );
    const passedWeight = allSuggestions.filter(s => s.passing).reduce((sum, s) => sum + s.weight, 0);
    const score = Math.min(100, Math.max(0, Math.round(passedWeight)));

    const criticalBlockerIds = new Set([
      'contact-essential',
      'section-skills',
      'skills-count',
      'section-education',
      'section-practical-exp',
      'section-projects',
      'section-experience',
      'section-work-projects'
    ]);
    const hasCriticalBlockers = pendingSuggestions.some(s => criticalBlockerIds.has(s.id));
    const isReady = score >= 75 && !hasCriticalBlockers;
    return { isReady, score, hasCriticalBlockers };
  };

  const handleStartNewAnalysis = () => {
    const readiness = checkResumeReadiness();
    if (!readiness.isReady) {
      setIsReadinessGateOpen(true);
      setIsJobDiscoveryOpen(false);
    } else {
      setIsJobDiscoveryOpen(true);
    }
  };

  // Guard Job Discovery modal: if opened directly or on refresh while resume is unready, show readiness modal
  useEffect(() => {
    if (isJobDiscoveryOpen && resumeData) {
      const readiness = checkResumeReadiness();
      if (!readiness.isReady) {
        setIsJobDiscoveryOpen(false);
        setIsReadinessGateOpen(true);
      }
    }
  }, [isJobDiscoveryOpen, resumeData, deletedSuggestionIds]);

  const calculateATS = () => {
    if (!resumeData) return { score: 0, issues: {} as Record<string, string> };
    const allSuggestions = getATSSuggestions();
    const passedWeight = allSuggestions.filter(s => s.passing).reduce((sum, s) => sum + s.weight, 0);
    const score = Math.min(100, Math.max(0, Math.round(passedWeight)));

    const issues: Record<string, string> = {};
    allSuggestions.filter(s => !s.passing).forEach(s => {
      issues[s.id] = s.title;
    });
    return { score, issues };
  };

  // Toggle Save Job to Saved Jobs list
  const toggleSaveJob = (jobId: string) => {
    setSavedJobIds(prev => {
      const next = new Set(prev);
      if (next.has(jobId)) {
        next.delete(jobId);
        showToast({ type: 'info', title: 'Removed from Saved', message: 'Job removed from saved jobs.' });
      } else {
        next.add(jobId);
        showToast({ type: 'success', title: 'Job Saved', message: 'Job added to saved list.' });
      }
      storage.setSavedJobs(Array.from(next));
      return next;
    });
  };

  // Intelligent ATS Job Match Score Analyzer
  const calculateJobMatch = (resData: ResumeBuilderData | null, job: Job) => {
    if (!resData) return { score: 0, label: 'Not Ready', color: '#ef4444', isEmpty: true };

    // ── EMPTY RESUME GUARD: don't return fake scores for blank resumes ──
    const nameStr = (resData.name || resData.fullName || '').trim();
    const summaryStr = (resData.summary || '').trim();
    const skillsStr = [
      resData.skills?.programmingLanguages,
      resData.skills?.frameworksLibraries,
      resData.skills?.toolsPlatforms,
      resData.skills?.databases,
      resData.skills?.softSkills,
    ].filter(Boolean).join(' ').trim();
    const expCount = (resData.experience || []).filter(e => (e.role || e.company || '').trim().length > 1).length;
    const eduCount = (resData.education || []).filter(e => (e.institution || e.degree || '').trim().length > 1).length;

    // Resume is considered empty when it has no name AND no real content
    const isEmptyResume = nameStr.length < 2 && summaryStr.length < 10 && skillsStr.length < 5 && expCount === 0 && eduCount === 0;
    if (isEmptyResume) {
      return { score: 0, label: 'Not Ready', color: '#ef4444', isEmpty: true };
    }

    // 1. Gather all resume texts and tokens
    const candidateSkillsText = [
      resData.skills?.programmingLanguages,
      resData.skills?.frameworksLibraries,
      resData.skills?.toolsPlatforms,
      resData.skills?.databases,
      resData.skills?.softSkills,
      ...(resData.skills?.customCategories || []).map(c => c.skills),
      ...(resume?.parsedData?.extractedSkills || [])
    ].filter(Boolean).join(', ').toLowerCase();

    const resumeAllText = [
      resData.headline,
      resData.summary,
      candidateSkillsText,
      ...(resData.experience || []).map(e => `${e.role} ${e.company} ${e.description} ${e.technologies}`),
      ...(resData.projects || []).map(p => `${p.title} ${p.description} ${p.technologies}`),
      ...(resData.education || []).map(ed => `${ed.degree} ${ed.institution} ${ed.fieldOfStudy}`),
      ...(resData.certifications || []).map(c => typeof c === 'string' ? c : `${(c as any).name || ''} ${(c as any).issuer || ''}`),
      (resume?.parsedData as any)?.rawText || ''
    ].filter(Boolean).join(' ').toLowerCase();

    // 2. Tokenize and extract target job requirements & skills
    const rawJobSkills = job.skills || [];
    const extractedJobSkills: string[] = [];

    rawJobSkills.forEach(skillItem => {
      const parts = skillItem.split(/[,;\n•]+/).map(s => s.trim()).filter(s => s.length > 1);
      parts.forEach(p => {
        if (p.includes(' ') && !/^(spring boot|react js|react\.js|rest api|rest apis|data structures|machine learning|deep learning|cloud security|full stack|node js|node\.js|angular js|vue js|distributed systems|software engineer|microservices|distributed architecture)$/i.test(p)) {
          const tokens = p.split(/\s+/).filter(t => t.length > 1);
          extractedJobSkills.push(...tokens);
        } else {
          extractedJobSkills.push(p);
        }
      });
    });

    // Deep scanning of any job description, requirements & responsibilities
    const combinedJobText = [
      job.title || '',
      job.description || '',
      ...(job.requirements || []),
      ...(job.responsibilities || [])
    ].join(' ').toLowerCase();

    const techCatalog: { name: string; key: string; aliases: string[] }[] = [
      { name: 'Delta Lake', key: 'delta lake', aliases: ['delta lake', 'deltalake'] },
      { name: 'PySpark / Spark', key: 'pyspark', aliases: ['pyspark', 'apache spark', 'spark'] },
      { name: 'SQL', key: 'sql', aliases: ['sql', 'mysql', 'postgresql', 'postgres', 'oracle', 'sqlite', 'plsql', 'tsql', 'database'] },
      { name: 'Python', key: 'python', aliases: ['python', 'py3', 'django', 'fastapi', 'flask'] },
      { name: 'Databricks', key: 'databricks', aliases: ['databricks'] },
      { name: 'MLflow', key: 'mlflow', aliases: ['mlflow'] },
      { name: 'Distributed Systems', key: 'distributed systems', aliases: ['distributed systems', 'distributed architecture', 'distributed computing', 'distributed transactions'] },
      { name: 'Apache Kafka', key: 'kafka', aliases: ['kafka', 'apache kafka', 'event streaming', 'message queue'] },
      { name: 'Microservices', key: 'microservices', aliases: ['microservices', 'microservice', 'micro-services'] },
      { name: 'Docker / Containers', key: 'docker', aliases: ['docker', 'container', 'containers', 'containerization'] },
      { name: 'Kubernetes', key: 'kubernetes', aliases: ['kubernetes', 'k8s'] },
      { name: 'AWS Cloud', key: 'aws', aliases: ['aws', 'amazon web services', 'ec2', 's3', 'lambda'] },
      { name: 'Azure Cloud', key: 'azure', aliases: ['azure', 'microsoft azure', 'azure devops'] },
      { name: 'GCP Cloud', key: 'gcp', aliases: ['gcp', 'google cloud', 'bigquery'] },
      { name: 'Spring Boot', key: 'spring boot', aliases: ['spring boot', 'springboot', 'spring framework'] },
      { name: 'Java', key: 'java', aliases: ['java', 'core java', 'j2ee'] },
      { name: 'React.js', key: 'react', aliases: ['react', 'react.js', 'reactjs'] },
      { name: 'TypeScript', key: 'typescript', aliases: ['typescript', 'ts'] },
      { name: 'Node.js', key: 'node.js', aliases: ['node.js', 'nodejs', 'node js'] },
      { name: 'GraphQL', key: 'graphql', aliases: ['graphql'] },
      { name: 'Redis', key: 'redis', aliases: ['redis', 'caching'] },
      { name: 'MongoDB', key: 'mongodb', aliases: ['mongodb', 'mongo', 'nosql'] },
      { name: 'Terraform', key: 'terraform', aliases: ['terraform', 'iac'] },
      { name: 'CI/CD Pipelines', key: 'ci/cd', aliases: ['ci/cd', 'cicd', 'jenkins', 'github actions', 'gitlab ci'] },
      { name: 'Apache Airflow', key: 'airflow', aliases: ['airflow', 'apache airflow'] },
      { name: 'Snowflake', key: 'snowflake', aliases: ['snowflake'] },
      { name: 'REST APIs', key: 'rest apis', aliases: ['rest', 'rest api', 'rest apis', 'restful', 'restful api'] },
      { name: 'Git / GitHub', key: 'git', aliases: ['git', 'github', 'gitlab', 'version control'] },
      { name: 'Machine Learning', key: 'machine learning', aliases: ['machine learning', 'ml', 'deep learning', 'scikit-learn', 'tensorflow', 'pytorch'] }
    ];

    techCatalog.forEach(tech => {
      const isPresentInJob = tech.aliases.some(alias => combinedJobText.includes(alias));
      if (isPresentInJob && !extractedJobSkills.includes(tech.key)) {
        extractedJobSkills.push(tech.key);
      }
    });

    if (extractedJobSkills.length < 5 && job.requirements && job.requirements.length > 0) {
      job.requirements.forEach(req => {
        const matches = req.match(/[A-Z][a-zA-Z0-9.+#/]+/g);
        const reqTokens: string[] = matches ? Array.from(matches) : [];
        reqTokens.forEach(tok => {
          if (tok.length > 2 && !['The', 'And', 'With', 'For', 'Work', 'Team', 'Have', 'Must', 'Required'].includes(tok)) {
            extractedJobSkills.push(tok.toLowerCase());
          }
        });
      });
    }

    const uniqueJobSkills = Array.from(new Set(extractedJobSkills.map(s => s.trim().toLowerCase()))).filter(s => s.length > 1);

    // 3. Calculate Skills Match (50% weight) with tech aliases
    let matchedSkillsCount = 0;
    const skillAliases: Record<string, string[]> = {
      'software engineer': ['software engineer', 'software engineering', 'software developer', 'full stack developer', 'full stack engineer'],
      'distributed systems': ['distributed systems', 'distributed architecture', 'distributed computing', 'distributed transactions'],
      'microservices': ['microservices', 'microservice', 'micro-services'],
      'kafka': ['kafka', 'apache kafka', 'message queue', 'event streaming'],
      'java': ['java', 'j2ee', 'core java'],
      'spring': ['spring', 'spring boot', 'spring mvc'],
      'spring boot': ['spring boot', 'springboot'],
      'react': ['react', 'react.js', 'reactjs'],
      'react.js': ['react', 'react.js', 'reactjs'],
      'javascript': ['javascript', 'js', 'es6', 'typescript'],
      'typescript': ['typescript', 'ts'],
      'sql': ['sql', 'mysql', 'postgresql', 'postgres', 'oracle', 'sqlite', 'database'],
      'rest': ['rest', 'rest api', 'rest apis', 'restful', 'restful api'],
      'rest apis': ['rest', 'rest api', 'rest apis', 'restful', 'restful api'],
      'git': ['git', 'github', 'gitlab', 'git/github', 'version control'],
      'git/github': ['git', 'github', 'gitlab', 'git/github'],
      'mongodb': ['mongodb', 'mongo', 'nosql'],
      'aws': ['aws', 'amazon web services', 'ec2', 's3', 'lambda'],
      'docker': ['docker', 'container', 'containerization'],
      'kubernetes': ['kubernetes', 'k8s'],
      'terraform': ['terraform', 'iac'],
      'python': ['python', 'django', 'fastapi', 'flask'],
      'html': ['html', 'html5', 'html/css'],
      'css': ['css', 'css3', 'html/css', 'tailwind', 'bootstrap'],
      'html/css': ['html', 'css', 'html/css'],
      'data structures': ['data structures', 'algorithms', 'dsa', 'problem-solving'],
      'technical certification': ['technical certification', 'professional certification', 'certification', 'certified'],
      'fullstack': ['fullstack', 'full stack', 'full-stack'],
      'hibernate': ['hibernate', 'orm', 'jpa'],
      'computer science': ['computer science', 'computer science and engineering', 'cse', 'b.tech'],
      'mlflow': ['mlflow'],
      'delta lake': ['delta lake', 'deltalake'],
      'pyspark': ['pyspark', 'apache spark', 'spark'],
      'databricks': ['databricks'],
      'redis': ['redis'],
      'graphql': ['graphql'],
      'ci/cd': ['ci/cd', 'cicd', 'jenkins', 'github actions'],
      'airflow': ['airflow', 'apache airflow'],
      'snowflake': ['snowflake']
    };

    const strongKeywords: { keyword: string; status: 'Perfect' | 'Present' | 'Partial' | 'Missing'; reason: string }[] = [];
    const missingKeywords: { keyword: string; status: 'Missing'; reason: string }[] = [];

    uniqueJobSkills.forEach(jobSkill => {
      const aliases = skillAliases[jobSkill] || [jobSkill];
      const isMatched = aliases.some(alias => resumeAllText.includes(alias));
      const displayKey = jobSkill.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

      const inSkills = aliases.some(alias => (
        (resData.skills?.programmingLanguages || '').toLowerCase().includes(alias) ||
        (resData.skills?.frameworksLibraries || '').toLowerCase().includes(alias) ||
        (resData.skills?.toolsPlatforms || '').toLowerCase().includes(alias) ||
        (resData.skills?.databases || '').toLowerCase().includes(alias)
      ));
      const inExpOrProjects = aliases.some(alias => (
        (resData.experience || []).some(e => ((e.description || '') + ' ' + (e.technologies || '')).toLowerCase().includes(alias)) ||
        (resData.projects || []).some(p => ((p.description || '') + ' ' + (p.technologies || '')).toLowerCase().includes(alias))
      ));

      if (isMatched) {
        matchedSkillsCount++;
        let status: 'Perfect' | 'Present' | 'Partial' = 'Perfect';
        let reason = 'Direct match with candidate profile skills and experience.';

        if (inSkills && inExpOrProjects) {
          status = 'Perfect';
          if (jobSkill.includes('software engineer')) {
            reason = 'Present in your resume headline & verified in work experience ("Software Engineer"). Direct match with role title.';
          } else if (jobSkill.includes('computer science')) {
            reason = 'B.Tech in Computer Science & Engineering satisfies educational qualification.';
          } else if (jobSkill.includes('java') || jobSkill.includes('spring')) {
            reason = 'Extensively demonstrated across programming languages, backend services, and project implementations.';
          } else if (jobSkill.includes('rest')) {
            reason = 'Demonstrated in REST API design, endpoint controllers, and client integrations.';
          } else {
            reason = `Extensively demonstrated in technical skills, project implementation, and work descriptions.`;
          }
        } else if (inExpOrProjects) {
          status = 'Present';
          reason = `Demonstrated in practical project experience, but not explicitly highlighted in technical skills list.`;
        } else {
          status = 'Partial';
          reason = `Listed in skills section, but not demonstrated with measurable outcomes in work experience or projects.`;
        }

        strongKeywords.push({
          keyword: displayKey,
          status,
          reason
        });
      } else {
        let reason = `We found this skill in the ${job.company || 'target'} job description.`;
        if (jobSkill.includes('distributed')) {
          reason = 'There is no distributed systems in your resume. Key requirement for payment & transaction architecture.';
        } else {
          reason = `There is no ${jobSkill} in your resume. Adding this keyword crumb will boost your ATS match score.`;
        }
        missingKeywords.push({
          keyword: displayKey,
          status: 'Missing',
          reason
        });
      }
    });

    // Ensure Computer Science is in strongKeywords if candidate has degree
    const hasCsDegree = (resData.education || []).some(ed => {
      const deg = (ed.degree || '').toLowerCase();
      const major = (ed.fieldOfStudy || '').toLowerCase();
      return deg.includes('computer science') || major.includes('computer science') || deg.includes('b.tech');
    });
    if (hasCsDegree && !strongKeywords.some(k => k.keyword.toLowerCase().includes('computer science'))) {
      strongKeywords.unshift({
        keyword: 'Computer Science / related field of study',
        status: 'Perfect',
        reason: 'No improvements needed — degree in Computer Science is perfectly integrated.'
      });
    }

    const skillRatio = uniqueJobSkills.length > 0 ? matchedSkillsCount / uniqueJobSkills.length : 0.6;
    const skillScore = Math.min(100, Math.round(skillRatio * 100));

    // 4. Calculate Role & Title Alignment (25% weight)
    const jobTitleTokens = (job.title || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(t => t.length > 2);
    let titleMatches = 0;
    const candidateRoleContext = [
      resData.headline,
      ...(resData.experience || []).map(e => e.role),
      resData.summary
    ].filter(Boolean).join(' ').toLowerCase();

    jobTitleTokens.forEach(tok => {
      if (candidateRoleContext.includes(tok)) titleMatches++;
    });

    const titleScore = jobTitleTokens.length > 0
      ? Math.min(100, Math.round((titleMatches / jobTitleTokens.length) * 100))
      : 70;

    // 5. Calculate Experience Fit (15% weight)
    const requiredYears = job.experienceRequiredYears || 2;
    const candidateYears = (resData.experience && resData.experience.length > 0)
      ? resData.experience.length * 1.5
      : 1.0;

    let expScore = 75;
    if (candidateYears >= requiredYears) {
      expScore = 95;
    } else if (candidateYears >= requiredYears * 0.7) {
      expScore = 80;
    } else if (candidateYears >= requiredYears * 0.4) {
      expScore = 50;
    } else {
      expScore = 25;
    }

    // 6. Calculate Education & Domain Fit (10% weight)
    let eduScore = 70;
    const hasDegree = (resData.education || []).some(ed => {
      const deg = (ed.degree || '').toLowerCase();
      const major = (ed.fieldOfStudy || '').toLowerCase();
      return deg.includes('b.tech') || deg.includes('b.e.') || deg.includes('bachelor') || deg.includes('master') || deg.includes('cs') || major.includes('computer') || major.includes('information');
    });
    if (hasDegree) eduScore = 95;

    // 7. Composite ATS Match Score
    // IMPORTANT: Never use job.matchScore (backend default) as it gives the same score for all jobs.
    // Always compute purely from resume content vs job description.
    const computedScore = Math.round(
      (skillScore * 0.40) +
      (titleScore * 0.25) +
      (expScore * 0.20) +
      (eduScore * 0.15)
    );

    const finalScore = Math.min(98, Math.max(5, computedScore));
    const label = finalScore >= 75 ? 'Strong Match' : finalScore >= 45 ? 'Fair Match' : 'Poor Match';
    const color = finalScore >= 75 ? '#22c55e' : finalScore >= 45 ? '#f97316' : '#ef4444';

    // 8. Generate Good-to-Have Keywords (Reference Image 5)
    const goodToHaveKeywords: { keyword: string; status: 'Perfect' | 'Matched' | 'Partial Match' | 'Missing' | 'Needs Improvement'; reason: string }[] = [];
    const hasCertifications = (resData.certifications && resData.certifications.length > 0);
    goodToHaveKeywords.push({
      keyword: 'Technical Certification',
      status: hasCertifications ? 'Matched' : 'Missing',
      reason: hasCertifications
        ? 'Technical certifications detected and verified in your resume.'
        : '1 Weak Keyword Missing: No technical or professional certification detected in resume.'
    });

    const candidateFullSkills = [
      resData.skills?.programmingLanguages,
      resData.skills?.frameworksLibraries,
      resData.skills?.toolsPlatforms,
      resData.skills?.databases,
      resData.skills?.softSkills,
      ...(resData.skills?.customCategories || []).map(c => c.skills)
    ].filter(Boolean).join(' ').toLowerCase();

    ['React', 'Hibernate', 'Docker', 'AWS'].forEach(goodKey => {
      const isPresent = candidateFullSkills.includes(goodKey.toLowerCase()) || resumeAllText.includes(goodKey.toLowerCase());
      goodToHaveKeywords.push({
        keyword: goodKey,
        status: isPresent ? 'Matched' : 'Missing',
        reason: isPresent
          ? `Demonstrated in technical skills and competencies (${goodKey}).`
          : `Recommended auxiliary tool: Adding ${goodKey} highlights broader full-stack capabilities.`
      });
    });

    // 9. Generate Role Alignment Criteria (Reference Image 5)
    const roleAlignmentCriteria: { criterion: string; status: 'Met' | 'Partial' | 'Not Met'; reason: string }[] = [
      {
        criterion: 'Bachelor level degree or equivalent in Computer Science, or related field of study.',
        status: hasCsDegree ? 'Met' : 'Not Met',
        reason: hasCsDegree
          ? 'Demonstrated in education: Degree in Computer Science & Engineering satisfies educational qualification.'
          : 'Educational requirement recommends a degree in Computer Science or an allied technical discipline.'
      },
      {
        criterion: `${job.experienceRequiredYears || '2 - 4'} YOE in relevant engineering domain`,
        status: candidateYears >= requiredYears ? 'Met' : candidateYears >= requiredYears * 0.7 ? 'Partial' : 'Not Met',
        reason: candidateYears >= requiredYears
          ? `Candidate satisfies requirement with approximately ${candidateYears.toFixed(1)} years of practical software engineering experience.`
          : `Candidate has approx. ${candidateYears.toFixed(1)} years experience; role requests ${requiredYears}+ years.`
      },
      {
        criterion: 'Full stack web application development & deployment',
        status: 'Met',
        reason: 'Demonstrated in work experience and technical projects with frontend, backend, and database integration.'
      }
    ];

    // 10. Genuine Evaluation: 7 Strict Readiness Criteria for Apply Ready
    // 1. Personal Information: Full name (min 3 chars), valid email, valid phone (min 7 digits)
    const resolvedFullName = (resData.fullName || resData.name || [resData.firstName, resData.lastName].filter(Boolean).join(' ') || '').trim();
    const hasFullName = Boolean(resolvedFullName.length >= 3);
    const hasValidEmail = Boolean(resData.email && resData.email.includes('@') && resData.email.includes('.'));
    const cleanPhone = (resData.phone || '').replace(/[^0-9xX+]/g, '');
    const hasValidPhone = cleanPhone.length >= 7 || (Boolean(resData.phone) && resData.phone.trim().length >= 7);
    const hasPersonalInfo = hasFullName && hasValidEmail && hasValidPhone;

    // 2. Contact & Location: Current location (min 2 chars)
    const resolvedLocation = (resData.location || [resData.city, resData.state, resData.country].filter(Boolean).join(', ') || '').trim();
    const hasLocation = Boolean(resolvedLocation.length >= 2);

    // 3. Education: At least 1 entry with institution and degree
    const hasEducation = Boolean(
      resData.education &&
      resData.education.length > 0 &&
      resData.education.some(ed => (ed.institution || '').trim().length > 0 && (ed.degree || '').trim().length > 0)
    );

    // 4. Relevant Skills: At least 5 technical/domain skills
    const rawSkillsList = [
      resData.skills?.programmingLanguages,
      resData.skills?.frameworksLibraries,
      resData.skills?.toolsPlatforms,
      resData.skills?.databases,
      resData.skills?.softSkills,
      ...(resData.skills?.customCategories || []).map(c => c.skills)
    ].filter(Boolean).flatMap(s => (s || '').split(/[,;\n\r/|]+/)).map(s => s.trim()).filter(s => s.length > 1);
    const uniqueCandidateSkills = Array.from(new Set(rawSkillsList));
    const skillsCount = uniqueCandidateSkills.length;
    const hasSkills = skillsCount >= 5;

    // 5. Work Experience or Projects: At least 1 work role or project description
    const hasWorkRole = Boolean(resData.experience && resData.experience.length > 0 && resData.experience.some(e => (e.role || '').trim().length > 0));
    const hasProject = Boolean(resData.projects && resData.projects.length > 0 && resData.projects.some(p => (p.title || '').trim().length > 0));
    const hasWorkOrProjects = hasWorkRole || hasProject;

    // 6. Professional Summary: Min 30 characters
    const hasSummary = Boolean(resData.summary && resData.summary.trim().length >= 30);

    // Calculate baseline profile readiness (out of 100)
    let computedReadiness = 0;
    if (hasPersonalInfo) computedReadiness += 20;
    if (hasLocation) computedReadiness += 10;
    if (hasEducation) computedReadiness += 20;
    if (hasSkills) computedReadiness += 20;
    if (hasWorkOrProjects) computedReadiness += 15;
    if (hasSummary) computedReadiness += 15;

    // 7. Readiness Threshold: Score >= 80%
    const meetsThreshold = computedReadiness >= 80;

    // Check if genuinely Apply Ready
    const isApplyReady = hasPersonalInfo && hasLocation && hasEducation && hasSkills && hasWorkOrProjects && hasSummary && meetsThreshold;

    const missingRequirements: { key: string; label: string; section: string; description: string }[] = [];
    if (!hasPersonalInfo) {
      missingRequirements.push({
        key: 'personal-info',
        label: 'Personal Information',
        section: 'personal',
        description: 'Provide full name (min 3 chars), valid email and phone number (min 7 digits).'
      });
    }
    if (!hasLocation) {
      missingRequirements.push({
        key: 'location',
        label: 'Contact & Location',
        section: 'personal',
        description: 'Add your current city/location to ensure recruiters know your work eligibility.'
      });
    }
    if (!hasEducation) {
      missingRequirements.push({
        key: 'education',
        label: 'Education',
        section: 'education',
        description: 'Include at least one degree with institution name.'
      });
    }
    if (!hasSkills) {
      missingRequirements.push({
        key: 'skills',
        label: 'Relevant Skills',
        section: 'skills',
        description: `Add at least 5 relevant technical/domain skills (currently ${skillsCount}).`
      });
    }
    if (!hasWorkOrProjects) {
      missingRequirements.push({
        key: 'experience',
        label: 'Work Experience or Projects',
        section: 'experience',
        description: 'Add at least one professional work role or key technical project.'
      });
    }
    if (!hasSummary) {
      missingRequirements.push({
        key: 'summary',
        label: 'Professional Summary',
        section: 'summary',
        description: 'Write a professional summary of at least 30 characters.'
      });
    }
    if (computedReadiness < 80 && missingRequirements.length === 0) {
      missingRequirements.push({
        key: 'readiness-threshold',
        label: 'Readiness Threshold',
        section: 'personal',
        description: 'Complete remaining resume profile details to reach 80% readiness threshold.'
      });
    }

    const eligibilityChecks = [
      { name: 'Personal Information', met: hasPersonalInfo, detail: 'Full name, valid email and phone' },
      { name: 'Contact & Location', met: hasLocation, detail: 'Current location' },
      { name: 'Education', met: hasEducation, detail: 'At least 1 institution and degree' },
      { name: 'Relevant Skills', met: hasSkills, detail: `At least 5 skills (current: ${skillsCount})` },
      { name: 'Work Experience or Projects', met: hasWorkOrProjects, detail: 'At least 1 work role or project' },
      { name: 'Professional Summary', met: hasSummary, detail: 'Summary with min 30 characters' },
      { name: 'Readiness Threshold', met: meetsThreshold, detail: `${computedReadiness}% (min 80% required)` }
    ];

    const readinessLabel = isApplyReady
      ? 'Apply Ready'
      : computedReadiness >= 70
        ? 'Good'
        : computedReadiness >= 55
          ? 'Developing'
          : computedReadiness >= 40
            ? 'Needs Improvement'
            : 'Not Ready';

    const fitAssessment = finalScore >= 60
      ? 'Strong fit for this role, few changes can make you standout.'
      : finalScore >= 45
        ? 'Moderate fit for this role, key improvements will boost your interview chances.'
        : 'Potential fit for this role, targeted optimizations needed to meet requirements.';

    return {
      score: finalScore,
      label,
      color,
      readinessScore: computedReadiness,
      readinessLabel,
      fitAssessment,
      matchedSkillsCount,
      totalSkillsCount: uniqueJobSkills.length,
      strongKeywords,
      goodToHaveKeywords,
      roleAlignmentCriteria,
      missingKeywords,
      missingPrioritySkills: missingKeywords.map(m => m.keyword),
      hasDistributedSystemsMissing: missingKeywords.some(m => m.keyword.toLowerCase().includes('distributed')),
      isApplyReady,
      eligibilityChecks,
      missingRequirements
    };
  };

  // Sync Analyzed Jobs from localStorage scoped to active resume ID
  useEffect(() => {
    if (id) {
      try {
        const raw = localStorage.getItem('ai_ats_job_optimizations');
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed)) {
            setAnalyzedJobs(parsed.filter((item: any) => item.resumeId === id));
          }
        } else {
          setAnalyzedJobs([]);
        }
      } catch (err) {
        console.error('Error loading job optimizations from localStorage:', err);
      }
    }
  }, [id]);

  const formatRelativeTime = (timestamp: string | number) => {
    const date = typeof timestamp === 'string' ? new Date(timestamp).getTime() : timestamp;
    if (!date || isNaN(date)) return 'Recently';
    const diffMs = Date.now() - date;
    const diffSec = Math.floor(diffMs / 1000);
    const diffMin = Math.floor(diffSec / 60);
    const diffHour = Math.floor(diffMin / 60);
    const diffDay = Math.floor(diffHour / 24);
    const diffMonth = Math.floor(diffDay / 30);

    if (diffMonth >= 1) return `${diffMonth} month${diffMonth > 1 ? 's' : ''} ago`;
    if (diffDay >= 1) return `${diffDay} day${diffDay > 1 ? 's' : ''} ago`;
    if (diffHour >= 1) return `${diffHour} hour${diffHour > 1 ? 's' : ''} ago`;
    if (diffMin >= 1) return `${diffMin} min${diffMin > 1 ? 's' : ''} ago`;
    return 'Just now';
  };

  const handleDeleteAnalysis = (analysisId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setAnalyzedJobs(prev => {
      const updated = prev.filter(a => a.id !== analysisId);
      try {
        const raw = localStorage.getItem('ai_ats_job_optimizations');
        if (raw) {
          const all: JobOptimizationAnalysis[] = JSON.parse(raw);
          const others = all.filter(a => a.id !== analysisId);
          localStorage.setItem('ai_ats_job_optimizations', JSON.stringify(others));
        }
      } catch (err) {
        console.error('Error removing job optimization from localStorage:', err);
      }
      return updated;
    });
    showToast({
      type: 'info',
      title: 'Analysis Removed',
      message: 'Job analysis has been removed.'
    });
  };

  const handleOptimizeJob = (job: Job) => {
    const match = calculateJobMatch(resumeData, job);

    const matchingSkills = match.strongKeywords.map(k => k.keyword);
    const missingSkills = match.missingKeywords.map(k => k.keyword);
    const keywordGaps = match.missingKeywords.map(k => `${k.keyword}: ${k.reason || 'Missing in resume'}`);

    const requiredYears = job.experienceRequiredYears || 2;
    const candidateYears = (resumeData?.experience && resumeData.experience.length > 0)
      ? resumeData.experience.length * 1.5
      : 1.0;
    const experienceAlignment = candidateYears >= requiredYears
      ? `Strong alignment: Candidate has approximately ${candidateYears} years of practical experience across relevant domains, satisfying the ${requiredYears}+ years requirement.`
      : `Candidate has approximately ${candidateYears} years of experience; role recommends ${requiredYears}+ years. Consider emphasizing relevant hands-on projects and internships to demonstrate senior competency.`;

    const improvementRecommendations = [
      ...(missingSkills.length > 0
        ? [`Incorporate priority missing skills: ${missingSkills.slice(0, 4).join(', ')} directly into your Skills & Competencies and Work Experience sections.`]
        : []),
      ...(match.hasDistributedSystemsMissing
        ? ['Emphasize distributed systems architecture, transactional integrity, and fault tolerance in your project descriptions.']
        : []),
      `Align your headline and professional summary with the target role (${job.title}).`,
      `Incorporate quantifiable impact metrics (e.g., % latency reduction, user throughput, system reliability) tailored to ${job.company}.`
    ];

    const optimizedSuggestions = [
      `Add "${job.title}" into your target headline and professional summary.`,
      ...(missingSkills.slice(0, 3).map(skill => `Add "${skill}" to your technical competencies with practical usage context.`)),
      `Review bullet points in Experience to highlight achievements aligning with ${job.company}'s technology stack.`
    ];

    const experienceRequiredStr = (job as any).experience || (job.experienceRequiredYears ? `${job.experienceRequiredYears} - ${job.experienceRequiredYears + 2} years` : `${(job as any).experienceLevel || '1 - 3'} years`);
    const employmentTypeStr = (job as any).employmentType || (job as any).type || 'Full Time';
    const salaryStr = typeof job.salary === 'string'
      ? job.salary
      : (job.salary && typeof job.salary === 'object' && 'min' in job.salary && 'max' in job.salary)
        ? `${(job.salary as any).currency === 'INR' ? '₹' : '$'}${(job.salary as any).min?.toLocaleString()} - ${(job.salary as any).currency === 'INR' ? '₹' : '$'}${(job.salary as any).max?.toLocaleString()} / ${(job.salary as any).period || 'yr'}`
        : 'Competitive';

    const newAnalysis: JobOptimizationAnalysis = {
      id: `opt-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
      candidateId: (resume as any)?.candidateId || 'candidate',
      resumeId: id || 'primary',
      jobId: job.id,
      timestamp: new Date().toISOString(),
      createdAt: Date.now(),
      matchScore: match.score,
      matchLabel: match.label,
      status: 'completed',
      jobTitle: job.title,
      companyName: job.company,
      companyLogo: job.companyLogo,
      location: job.location || 'Remote',
      experienceRequired: experienceRequiredStr,
      employmentType: employmentTypeStr,
      salary: salaryStr,
      jobDetails: {
        id: job.id,
        title: job.title,
        company: job.company,
        companyLogo: job.companyLogo,
        description: job.description,
        responsibilities: job.responsibilities,
        requirements: job.requirements,
        skills: job.skills,
        experience: experienceRequiredStr,
        location: job.location,
        employmentType: employmentTypeStr,
        salary: salaryStr
      },
      recommendations: {
        matchingSkills,
        missingSkills,
        keywordGaps,
        experienceAlignment,
        improvementRecommendations,
        optimizedSuggestions,
        overallFeedback: `Overall ${match.label} with an ATS score of ${match.score}%. Your profile demonstrates strong fundamentals. Addressing the highlighted gaps will maximize your interview shortlist probability at ${job.company}.`
      }
    };

    setAnalyzedJobs(prev => {
      const filtered = prev.filter(a => a.jobId !== job.id);
      const updated = [newAnalysis, ...filtered];
      try {
        const raw = localStorage.getItem('ai_ats_job_optimizations');
        const all: JobOptimizationAnalysis[] = raw ? JSON.parse(raw) : [];
        const others = all.filter(a => a.resumeId !== (id || 'primary') || a.jobId !== job.id);
        localStorage.setItem('ai_ats_job_optimizations', JSON.stringify([newAnalysis, ...others]));
      } catch (err) {
        console.error('Error saving optimization to localStorage:', err);
      }
      return updated;
    });

    setSelectedJobId(job.id);
    setIsJobDiscoveryOpen(false);
    setViewingJobInModal(null);
    showToast({
      type: 'success',
      title: 'Job Optimized Successfully',
      message: `Resume analyzed for ${job.title} at ${job.company} (${match.score}% - ${match.label}).`
    });
  };

  const handleSelectJobForOptimization = (job: Job) => {
    handleOptimizeJob(job);
  };

  const handleBackToAnalyzedJobs = () => {
    setSelectedJobId('');
    setSelectedAnalysisDetails(null);
    setSearchParams(prev => {
      const p = new URLSearchParams(prev);
      p.set('tab', 'job-optimize');
      p.delete('optimize_job_id');
      return p;
    });
  };

  const handleInitiateRestore = (record: OptimizationHistoryRecord) => {
    setRestoreTargetHistory(record);
  };

  const handleConfirmRestore = async () => {
    if (!restoreTargetHistory) return;
    if (restoreTargetHistory.resumeSnapshot) {
      handleUpdate(() => restoreTargetHistory.resumeSnapshot);
      if (id && restoreTargetHistory.jobId && restoreTargetHistory.id) {
        try {
          await candidateApi.restoreOptimizationVersion(id, restoreTargetHistory.jobId, restoreTargetHistory.id);
        } catch (err) {
          console.warn('Backend restore sync error:', err);
        }
      }
      showToast({
        type: 'success',
        title: 'Version Restored',
        message: `Restored resume to version from ${formatRelativeTime(restoreTargetHistory.timestamp)}.`
      });
    }
    setRestoreTargetHistory(null);
  };

  const getAvailableResumeSections = (data: ResumeBuilderData | null) => {
    if (!data) return [];
    const sections: { id: string; name: string; icon: React.ReactNode }[] = [];

    // 1. Personal Information (Always present)
    sections.push({
      id: 'profile',
      name: 'Personal Information',
      icon: <User className="w-4 h-4 text-purple-400" />
    });

    // 2. Professional Summary
    if (data.summary?.trim() || data.activeSections?.includes('summary')) {
      sections.push({
        id: 'summary',
        name: 'Professional Summary',
        icon: <FileText className="w-4 h-4 text-purple-400" />
      });
    }

    // 3. Work Experience
    if ((data.experience && data.experience.length > 0) || data.activeSections?.includes('experience')) {
      sections.push({
        id: 'experience',
        name: 'Work Experience',
        icon: <Briefcase className="w-4 h-4 text-purple-400" />
      });
    }

    // 4. Educations
    if ((data.education && data.education.length > 0) || data.activeSections?.includes('education')) {
      sections.push({
        id: 'education',
        name: 'Educations',
        icon: <GraduationCap className="w-4 h-4 text-purple-400" />
      });
    }

    // 5. Projects
    if ((data.projects && data.projects.length > 0) || data.activeSections?.includes('projects')) {
      sections.push({
        id: 'projects',
        name: 'Projects',
        icon: <Rocket className="w-4 h-4 text-purple-400" />
      });
    }

    // 6. Skills
    if (data.skills || data.activeSections?.includes('skills')) {
      sections.push({
        id: 'skills',
        name: 'Skills',
        icon: <Zap className="w-4 h-4 text-purple-400" />
      });
    }

    // 7. Certifications
    if ((data.certifications && data.certifications.length > 0) || data.activeSections?.includes('certifications')) {
      sections.push({
        id: 'certifications',
        name: 'Certifications',
        icon: <Award className="w-4 h-4 text-purple-400" />
      });
    }

    // 8. Awards
    if ((data.awards && data.awards.length > 0) || data.activeSections?.includes('awards')) {
      sections.push({
        id: 'awards',
        name: 'Awards & Achievements',
        icon: <Trophy className="w-4 h-4 text-purple-400" />
      });
    }

    const unique: typeof sections = [];
    const seen = new Set<string>();
    sections.forEach(s => {
      if (!seen.has(s.name)) {
        seen.add(s.name);
        unique.push(s);
      }
    });

    return unique;
  };

  const getJobOptimizationSuggestions = (
    activeJobAnalysis: JobOptimizationAnalysis | null,
    activeJob: Job | null,
    resData: ResumeBuilderData | null,
    existingMap: Record<string, JobOptimizationSuggestion[]>,
    resumeId: string
  ): JobOptimizationSuggestion[] => {
    if (!activeJobAnalysis) return [];
    const jobId = activeJobAnalysis.jobId;
    const key = `${resumeId}_${jobId}`;
    if (existingMap[key] && existingMap[key].length > 0) {
      return existingMap[key];
    }

    try {
      const raw = localStorage.getItem(`ai_ats_opt_suggs_${key}`);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return parsed;
        }
      }
    } catch {}

    const suggestions: JobOptimizationSuggestion[] = [];

    const candidateSkillsText = [
      resData?.skills?.programmingLanguages,
      resData?.skills?.frameworksLibraries,
      resData?.skills?.toolsPlatforms,
      resData?.skills?.databases,
      resData?.skills?.softSkills,
      ...(resData?.skills?.customCategories || []).map(c => c.skills)
    ].filter(Boolean).join(' ').toLowerCase();

    const allResumeText = [
      resData?.name,
      resData?.headline,
      resData?.summary,
      candidateSkillsText,
      ...(resData?.experience || []).map(e => `${e.role} ${e.company} ${e.description} ${e.technologies}`),
      ...(resData?.projects || []).map(p => `${p.title} ${p.description} ${p.technologies}`),
      ...(resData?.education || []).map(ed => `${ed.degree} ${ed.institution} ${ed.fieldOfStudy}`),
      ...(resData?.certifications || []).map(c => typeof c === 'string' ? c : `${(c as any).name || ''} ${(c as any).issuer || ''} ${(c as any).title || ''}`)
    ].filter(Boolean).join(' ').toLowerCase();

    const jobRequirements = (activeJob?.requirements || activeJobAnalysis.jobDetails?.requirements || []).join(' ').toLowerCase();
    const jobSkills = (activeJob?.skills || activeJobAnalysis.jobDetails?.skills || []);
    const jobDesc = (activeJob?.description || activeJobAnalysis.jobDetails?.description || '').toLowerCase();
    const combinedJobText = `${jobRequirements} ${jobSkills.join(' ').toLowerCase()} ${jobDesc}`;

    const hasJobCertRequirement =
      combinedJobText.includes('technical or professional certification') ||
      combinedJobText.includes('technical certification') ||
      combinedJobText.includes('professional certification') ||
      combinedJobText.includes('certification in domain');

    const candidateHasCert =
      Boolean(resData?.certifications && resData.certifications.length > 0) ||
      allResumeText.includes('certified') ||
      allResumeText.includes('certification');

    if (hasJobCertRequirement && !candidateHasCert) {
      suggestions.push({
        id: `sugg-${jobId}-cert`,
        keyword: 'Technical Certification / Professional Certification',
        promptText: 'Do you have experience with Technical Certification / Professional Certification?',
        whyItMatters: 'Found in job requirements: Technical or Professional Certification in Domain is preferred for this role.',
        relevantSection: 'Certifications',
        status: 'pending'
      });
    }

    const coreRequirementsToCheck = [
      {
        key: 'database',
        tokens: ['database', 'relational', 'nosql', 'rdbms', 'postgresql', 'mongodb'],
        label: 'Relational Databases / NoSQL',
        prompt: 'Can you highlight your experience with Relational Databases / NoSQL?',
        category: 'Skills',
        reason: 'Relational & NoSQL database proficiencies are fundamental for backend data design and transactions.'
      },
      {
        key: 'cicd',
        tokens: ['ci/cd', 'cicd', 'continuous integration', 'continuous delivery', 'pipeline', 'jenkins', 'github actions'],
        label: 'CI/CD',
        prompt: 'Does your experience include CI/CD?',
        category: 'Skills',
        reason: 'Automated CI/CD build pipelines ensure reliable software deployment and testing.'
      },
      {
        key: 'cloud',
        tokens: ['azure', 'aws', 'gcp', 'cloud', 'amazon web services', 'google cloud'],
        label: 'Azure / AWS / GCP',
        prompt: 'Do you have experience with Azure / AWS / GCP?',
        category: 'Skills',
        reason: 'Cloud infrastructure experience is crucial for deploying scalable modern services.'
      },
      {
        key: 'hibernate',
        tokens: ['hibernate'],
        label: 'Hibernate',
        prompt: 'Do you have experience with Hibernate?',
        category: 'Skills',
        reason: 'Recommended ORM framework for Java and Spring Boot enterprise architectures.'
      },
      {
        key: 'docker',
        tokens: ['docker', 'container', 'kubernetes'],
        label: 'Docker / Containers',
        prompt: 'Do you have experience with Docker / Containers?',
        category: 'Skills',
        reason: 'Containerization is critical for microservices packaging and modern cloud deployment.'
      }
    ];

    coreRequirementsToCheck.forEach((req) => {
      const isDemandedInJob = req.tokens.some(t => combinedJobText.includes(t));
      const isPresentInResume = req.tokens.some(t => allResumeText.includes(t));
      if (isDemandedInJob && !isPresentInResume && !suggestions.some(s => s.keyword === req.label)) {
        suggestions.push({
          id: `sugg-${jobId}-${req.key}`,
          keyword: req.label,
          promptText: req.prompt,
          whyItMatters: req.reason,
          relevantSection: req.category,
          status: 'pending'
        });
      }
    });

    if (suggestions.length === 0 && activeJobAnalysis.goodToHaveKeywords) {
      activeJobAnalysis.goodToHaveKeywords.forEach((k) => {
        if (k.status === 'Missing' && !allResumeText.includes(k.keyword.toLowerCase())) {
          suggestions.push({
            id: `sugg-${jobId}-${k.keyword.toLowerCase().replace(/[^a-z0-9]/g, '-')}`,
            keyword: k.keyword,
            promptText: `Do you have experience with ${k.keyword}?`,
            whyItMatters: k.reason || `Recommended skill from target job description.`,
            relevantSection: 'Skills',
            status: 'pending'
          });
        }
      });
    }

    // Default baseline suggestions matching Reference Image 2 when no custom requirements matched
    if (suggestions.length === 0) {
      suggestions.push(
        {
          id: `sugg-${jobId}-db`,
          keyword: 'Relational Databases / NoSQL',
          promptText: 'Can you highlight your experience with Relational Databases / NoSQL?',
          whyItMatters: 'Relational & NoSQL database competencies are fundamental for this role.',
          relevantSection: 'Skills',
          status: 'pending'
        },
        {
          id: `sugg-${jobId}-cicd`,
          keyword: 'CI/CD',
          promptText: 'Does your experience include CI/CD?',
          whyItMatters: 'Continuous integration and deployment pipelines ensure rapid automated delivery.',
          relevantSection: 'Skills',
          status: 'pending'
        },
        {
          id: `sugg-${jobId}-cloud`,
          keyword: 'Azure / AWS / GCP',
          promptText: 'Do you have experience with Azure / AWS / GCP?',
          whyItMatters: 'Cloud infrastructure proficiency is essential for modern distributed applications.',
          relevantSection: 'Skills',
          status: 'pending'
        }
      );
    }

    return suggestions;
  };

  const handleContinueOptimizing = () => {
    const readiness = checkResumeReadiness();
    if (!readiness.isReady) {
      setIsReadinessGateOpen(true);
      return;
    }
    setIsOptimizeWorkflowActive(true);
    setOptimizeWorkflowStep(1);
    setSuggestedActionsTab('pending');
  };

  const handleExitOptimizationWorkflow = () => {
    setIsOptimizeWorkflowActive(false);
  };

  const handleDeleteSuggestion = (suggId: string) => {
    const activeJobId = optimizeJobIdParam || selectedJobId;
    const activeJobAnalysis = (activeJobId ? analyzedJobs.find(a => a.jobId === activeJobId) : null) || selectedAnalysisDetails;
    if (!activeJobAnalysis) return;

    const histKey = `${id || 'primary'}_${activeJobAnalysis.jobId}`;
    const currentList = jobSuggestionsMap[histKey] || getJobOptimizationSuggestions(activeJobAnalysis, (activeJobAnalysis.jobDetails as any), resumeData, jobSuggestionsMap, id || 'primary');

    const updatedList = currentList.map(s => {
      if (s.id === suggId) {
        return { ...s, status: 'deleted' as const };
      }
      return s;
    });

    setJobSuggestionsMap(prev => ({ ...prev, [histKey]: updatedList }));
    try {
      localStorage.setItem(`ai_ats_opt_suggs_${histKey}`, JSON.stringify(updatedList));
    } catch {}

    showToast({
      type: 'info',
      title: 'Action Removed',
      message: 'Suggestion moved to Deleted tab.'
    });
  };

  const handleRestoreOptSuggestion = (suggId: string) => {
    const activeJobId = optimizeJobIdParam || selectedJobId;
    const activeJobAnalysis = (activeJobId ? analyzedJobs.find(a => a.jobId === activeJobId) : null) || selectedAnalysisDetails;
    if (!activeJobAnalysis) return;

    const histKey = `${id || 'primary'}_${activeJobAnalysis.jobId}`;
    const currentList = jobSuggestionsMap[histKey] || [];

    const updatedList = currentList.map(s => {
      if (s.id === suggId) {
        return { ...s, status: 'pending' as const, decision: undefined };
      }
      return s;
    });

    setJobSuggestionsMap(prev => ({ ...prev, [histKey]: updatedList }));
    try {
      localStorage.setItem(`ai_ats_opt_suggs_${histKey}`, JSON.stringify(updatedList));
    } catch {}

    showToast({
      type: 'success',
      title: 'Action Restored',
      message: 'Suggestion moved back to Pending tab.'
    });
  };

  const handleApplySuggestionDecision = async () => {
    if (!activeSuggestionForModal) return;
    const activeJobId = optimizeJobIdParam || selectedJobId;
    const activeJobAnalysis = (activeJobId ? analyzedJobs.find(a => a.jobId === activeJobId) : null) || selectedAnalysisDetails;
    if (!activeJobAnalysis) return;

    const suggId = activeSuggestionForModal.id;
    const action = suggestionActionType;
    const section = suggestionSelectedSection;
    const context = suggestionContextAi.trim();

    if (action === 'specific_place' && !section) {
      showToast({
        type: 'error',
        title: 'Section Required',
        message: 'Please choose which resume section to add this requirement to.'
      });
      return;
    }

    const histKey = `${id || 'primary'}_${activeJobAnalysis.jobId}`;
    const currentList = jobSuggestionsMap[histKey] || getJobOptimizationSuggestions(activeJobAnalysis, (activeJobAnalysis.jobDetails as any), resumeData, jobSuggestionsMap, id || 'primary');

    const updatedList = currentList.map(s => {
      if (s.id === suggId) {
        return {
          ...s,
          status: 'completed' as const,
          decision: {
            action,
            section: action === 'specific_place' ? section : (action === 'ai_choose' ? 'Skills' : undefined),
            context: context || undefined,
            timestamp: Date.now()
          }
        };
      }
      return s;
    });

    setJobSuggestionsMap(prev => ({ ...prev, [histKey]: updatedList }));
    try {
      localStorage.setItem(`ai_ats_opt_suggs_${histKey}`, JSON.stringify(updatedList));
    } catch (e) {
      console.error('Failed to save suggestions:', e);
    }

    const decisionDescription = action === 'specific_place'
      ? `Added '${activeSuggestionForModal.keyword}' to ${section}${context ? ` with context: "${context}"` : ''}`
      : action === 'ai_choose'
        ? `Applied AI placement for '${activeSuggestionForModal.keyword}' in Skills`
        : `Skipped requirement '${activeSuggestionForModal.keyword}'`;

    // Apply change directly to candidate's resume content if adding
    let updatedSnapshot: ResumeBuilderData | null = null;
    if (action !== 'do_not_add') {
      const keyword = activeSuggestionForModal.keyword;
      handleUpdate((prev) => {
        const next = { ...prev };
        const lowerKey = keyword.toLowerCase();

        if (action === 'specific_place') {
          const lowerSec = (section || '').toLowerCase();
          if (lowerSec.includes('skill')) {
            if (lowerKey.includes('database') || lowerKey.includes('nosql') || lowerKey.includes('sql') || lowerKey.includes('mongo')) {
              next.skills = { ...next.skills, databases: next.skills.databases ? `${next.skills.databases}, ${keyword}` : keyword };
            } else if (lowerKey.includes('ci/cd') || lowerKey.includes('docker') || lowerKey.includes('cloud') || lowerKey.includes('azure') || lowerKey.includes('aws') || lowerKey.includes('gcp')) {
              next.skills = { ...next.skills, toolsPlatforms: next.skills.toolsPlatforms ? `${next.skills.toolsPlatforms}, ${keyword}` : keyword };
            } else if (lowerKey.includes('spring') || lowerKey.includes('hibernate') || lowerKey.includes('react') || lowerKey.includes('angular')) {
              next.skills = { ...next.skills, frameworksLibraries: next.skills.frameworksLibraries ? `${next.skills.frameworksLibraries}, ${keyword}` : keyword };
            } else {
              next.skills = { ...next.skills, toolsPlatforms: next.skills.toolsPlatforms ? `${next.skills.toolsPlatforms}, ${keyword}` : keyword };
            }
          } else if (lowerSec.includes('summary')) {
            next.summary = next.summary
              ? `${next.summary.trim()} Proficient in ${keyword} with practical implementation experience.`
              : `Experienced professional with demonstrated expertise in ${keyword}.`;
          } else if (lowerSec.includes('education')) {
            if (next.education && next.education.length > 0) {
              const edu = { ...next.education[0] };
              edu.details = edu.details ? `${edu.details}; Coursework in ${keyword}` : `Coursework in ${keyword}`;
              next.education = [edu, ...next.education.slice(1)];
            }
          } else if (lowerSec.includes('project')) {
            if (next.projects && next.projects.length > 0) {
              const p = { ...next.projects[0] };
              p.technologies = p.technologies ? `${p.technologies}, ${keyword}` : keyword;
              next.projects = [p, ...next.projects.slice(1)];
            }
          } else if (lowerSec.includes('cert')) {
            next.certifications = [
              ...(next.certifications || []),
              {
                id: `cert-${Date.now()}`,
                title: keyword,
                issuer: 'Certified Professional',
                issueDate: '2024',
                visible: true
              }
            ];
            if (!next.activeSections.includes('certifications')) {
              next.activeSections = [...next.activeSections, 'certifications'];
            }
          }
        } else if (action === 'ai_choose') {
          // AI Placement directly into Skills
          if (lowerKey.includes('database') || lowerKey.includes('nosql')) {
            next.skills = { ...next.skills, databases: next.skills.databases ? `${next.skills.databases}, ${keyword}` : keyword };
          } else if (lowerKey.includes('ci/cd') || lowerKey.includes('docker') || lowerKey.includes('cloud') || lowerKey.includes('azure') || lowerKey.includes('aws') || lowerKey.includes('gcp')) {
            next.skills = { ...next.skills, toolsPlatforms: next.skills.toolsPlatforms ? `${next.skills.toolsPlatforms}, ${keyword}` : keyword };
          } else if (lowerKey.includes('cert')) {
            next.certifications = [
              ...(next.certifications || []),
              {
                id: `cert-${Date.now()}`,
                title: keyword,
                issuer: 'Industry Certification',
                issueDate: '2024',
                visible: true
              }
            ];
            if (!next.activeSections.includes('certifications')) {
              next.activeSections = [...next.activeSections, 'certifications'];
            }
          } else {
            next.skills = { ...next.skills, frameworksLibraries: next.skills.frameworksLibraries ? `${next.skills.frameworksLibraries}, ${keyword}` : keyword };
          }
        }
        updatedSnapshot = JSON.parse(JSON.stringify(next));
        return next;
      });
    }

    // Record Genuine Optimization History for this applied change
    const newHistRecord: OptimizationHistoryRecord = {
      id: `opt-${Date.now()}`,
      candidateId: (user as any)?.id || 'cand-current',
      resumeId: id || 'primary',
      jobId: activeJobAnalysis.jobId,
      analysisId: activeJobAnalysis.id || `analysis-${activeJobAnalysis.jobId}`,
      jobTitle: activeJobAnalysis.jobTitle || activeJobAnalysis.jobDetails?.title,
      companyName: activeJobAnalysis.companyName || activeJobAnalysis.jobDetails?.company,
      location: activeJobAnalysis.location || activeJobAnalysis.jobDetails?.location,
      previousScore: activeJobAnalysis.matchScore || 65,
      scoreAfter: Math.min(98, (activeJobAnalysis.matchScore || 65) + (action === 'do_not_add' ? 0 : 5)),
      status: 'Completed',
      timestamp: Date.now(),
      changesApplied: {
        skillsAdded: action !== 'do_not_add' ? [activeSuggestionForModal.keyword] : [],
        description: decisionDescription,
        completedActions: [decisionDescription],
        decisions: [{
          keyword: activeSuggestionForModal.keyword,
          action,
          section: action === 'specific_place' ? section : (action === 'ai_choose' ? 'Skills' : undefined),
          context: context || undefined,
          timestamp: Date.now()
        }]
      },
      resumeSnapshot: updatedSnapshot || JSON.parse(JSON.stringify(resumeData || {}))
    };

    setJobOptimizationHistories(prev => {
      const existing = prev[histKey] || [];
      const updated = [newHistRecord, ...existing];
      try {
        localStorage.setItem(`ai_ats_opt_hist_${histKey}`, JSON.stringify(updated));
      } catch (e) {
        console.error('Error saving history to localStorage:', e);
      }
      return { ...prev, [histKey]: updated };
    });

    if (id && activeJobAnalysis.jobId) {
      try {
        await candidateApi.applyJobOptimization(id, activeJobAnalysis.jobId, {
          changesAppliedDescription: decisionDescription,
          status: 'Completed',
          scoreAfter: newHistRecord.scoreAfter,
          decision: {
            keyword: activeSuggestionForModal.keyword,
            action,
            section,
            context
          }
        });
      } catch (err) {
        console.warn('Backend suggestion decision sync:', err);
      }
    }

    setActiveSuggestionForModal(null);
    setSuggestionSelectedSection('');
    setSuggestionContextAi('');
    setIsOptSectionDropdownOpen(false);

    showToast({
      type: 'success',
      title: action === 'do_not_add' ? 'Requirement Skipped' : 'Decision Saved',
      message: action === 'do_not_add'
        ? 'Requirement skipped. Resume unchanged.'
        : `Choice recorded for ${activeSuggestionForModal.keyword}.`
    });
  };

  const handleApplyOptimization = () => {
    const activeJobId = optimizeJobIdParam || selectedJobId;
    const activeJobAnalysis = analyzedJobs.find(a => a.jobId === activeJobId) || selectedAnalysisDetails;
    if (!activeJobAnalysis) return;

    const oldScore = activeJobAnalysis.matchScore;

    handleUpdate((prev) => {
      const next = { ...prev };

      if (optimizeDraft.updateHeadline) {
        next.headline = `${activeJobAnalysis.jobTitle} | Software Engineering Specialist`;
      }

      if (optimizeDraft.updateSummary) {
        next.summary = `Results-driven Software Engineer with extensive experience in ${activeJobAnalysis.jobTitle} development. Experienced in building responsive, scalable, database-driven web applications and modern service architectures. Proficient in Java, Spring Boot, REST APIs, and clean engineering practices with a strong focus on high-reliability distributed systems.`;
      }

      if (optimizeDraft.selectedSkills.length > 0) {
        const currentSkills = next.skills || {
          programmingLanguages: '',
          frameworksLibraries: '',
          toolsPlatforms: '',
          databases: '',
          softSkills: '',
          languages: ''
        };
        const currentFrameworks = currentSkills.frameworksLibraries
          ? currentSkills.frameworksLibraries.split(',').map(s => s.trim())
          : [];
        const toAdd = optimizeDraft.selectedSkills.filter(s => !currentFrameworks.includes(s));
        if (toAdd.length > 0) {
          next.skills = {
            ...currentSkills,
            frameworksLibraries: [...currentFrameworks, ...toAdd].join(', ')
          };
        }
      }

      return next;
    });

    const newScore = Math.min(96, oldScore + 8);

    const newHistoryRecord: OptimizationHistoryRecord = {
      id: `hist-${Date.now()}`,
      resumeId: id || 'primary',
      jobId: activeJobAnalysis.jobId,
      previousScore: oldScore,
      scoreAfter: newScore,
      status: 'Completed',
      timestamp: Date.now(),
      changesApplied: {
        skillsAdded: optimizeDraft.selectedSkills,
        summaryUpdated: optimizeDraft.updateSummary,
        headlineUpdated: optimizeDraft.updateHeadline,
        description: 'Applied role headline alignment, tailored summary, and integrated priority keywords.'
      },
      resumeSnapshot: JSON.parse(JSON.stringify(resumeData))
    };

    const histKey = `${id || 'primary'}_${activeJobAnalysis.jobId}`;
    setJobOptimizationHistories(prev => {
      const existing = prev[histKey] || [];
      const updated = [newHistoryRecord, ...existing];
      try {
        localStorage.setItem(`ai_ats_opt_hist_${histKey}`, JSON.stringify(updated));
      } catch (e) {
        console.error('Error saving history to localStorage:', e);
      }
      return { ...prev, [histKey]: updated };
    });

    setAnalyzedJobs(prev => {
      const updated = prev.map(a => a.jobId === activeJobAnalysis.jobId ? { ...a, matchScore: newScore, matchLabel: 'Strong Match' } : a);
      try {
        const raw = localStorage.getItem('ai_ats_job_optimizations');
        if (raw) {
          const all: JobOptimizationAnalysis[] = JSON.parse(raw);
          const newAll = all.map(a => (a.resumeId === (id || 'primary') && a.jobId === activeJobAnalysis.jobId) ? { ...a, matchScore: newScore, matchLabel: 'Strong Match' } : a);
          localStorage.setItem('ai_ats_job_optimizations', JSON.stringify(newAll));
        }
      } catch (e) {
        console.error('Error updating optimizations in localStorage:', e);
      }
      return updated;
    });

    setIsOptimizeModalOpen(false);
    showToast({
      type: 'success',
      title: 'Resume Optimized',
      message: `Successfully optimized resume for ${activeJobAnalysis.jobTitle}. ATS match updated to ${newScore}%.`
    });
  };

  // ─── COMPREHENSIVE AI BACKGROUND PROFILE ANALYZER & REPHRASER ───
  const handleRunAiProfileAnalysis = async (options?: {
    addSkill?: boolean;
    section?: string;
    context?: string;
    targetStep?: number;
  }) => {
    if (!resumeData) {
      showToast({ type: 'error', title: 'Error', message: 'No resume profile found to analyze.' });
      return;
    }

    const job = selectedJob;
    const currentResume = resumeData;

    // Open Incorporating Selected Keywords modal & initialize state
    setIsGeneratingSummary(true);
    setSummaryGenProgress(0);
    setSummaryGenStep(1);
    setSummaryGenStageText('Capturing current resume snapshot...');

    try {
      // ── STAGE 1: Process Candidate Profile & Added Credential (if any) ──
      const candidateName = `${currentResume.firstName || ''} ${currentResume.lastName || ''}`.trim() || currentResume.name || 'Candidate';
      const candidateHeadline = currentResume.headline || 'Software Developer';

      const allCandidateSkills = [
        currentResume.skills?.programmingLanguages,
        currentResume.skills?.frameworksLibraries,
        currentResume.skills?.toolsPlatforms,
        currentResume.skills?.databases,
        currentResume.skills?.softSkills,
        ...(currentResume.skills?.customCategories || []).map((c) => `${c.name}: ${c.skills}`),
      ].filter(Boolean).join(', ');

      const candidateExperience = (currentResume.experience || [])
        .map(
          (e) =>
            `${e.role} at ${e.company} (${e.startDate}-${e.endDate || 'Present'}): ${e.description || ''}`
        )
        .join('; ');

      const candidateProjects = (currentResume.projects || [])
        .map(
          (p) =>
            `${p.title} (${p.role || 'Developer'}): ${p.description || ''} Technologies: ${p.technologies || ''}.`
        )
        .join('; ');

      const candidateEducation = (currentResume.education || [])
        .map(
          (ed) =>
            `${ed.degree} from ${ed.institution} (${ed.fieldOfStudy || ''}${ed.cgpa ? `, CGPA: ${ed.cgpa}` : ''})`
        )
        .join('; ');

      // If user selected to add a skill / credential from the modal
      if (options?.addSkill) {
        const sec = options.section || 'certifications';
        const ctx = (options.context || '').trim();
        const skillKeyword = job?.skills?.[0] || 'Full Stack Development';

        handleUpdate((prev) => {
          if (sec === 'certifications') {
            const updatedCerts = [...(prev.certifications || [])];
            const certTitle = ctx
              ? `${ctx} Certification`
              : job
                ? `${job.title} Professional Certification`
                : 'Technical / Professional Certification';
            const exists = updatedCerts.some(
              (c) => c.title.toLowerCase() === certTitle.toLowerCase()
            );
            if (!exists) {
              updatedCerts.push({
                id: `cert-${Date.now()}`,
                title: certTitle,
                issuer: 'Accredited Certification Authority',
                issueDate: new Date().getFullYear().toString(),
                description: ctx
                  ? `Demonstrated applied competence: ${ctx}.`
                  : `Demonstrated technical competence aligned with ${job?.title || 'modern industry standards'}.`,
              });
            }
            return { ...prev, certifications: updatedCerts };
          } else if (sec === 'skills') {
            const currentProg = prev.skills?.programmingLanguages || '';
            const toAdd = ctx || skillKeyword;
            const updatedProg = currentProg.toLowerCase().includes(toAdd.toLowerCase())
              ? currentProg
              : currentProg
                ? `${currentProg}, ${toAdd}`
                : toAdd;
            return {
              ...prev,
              skills: {
                ...prev.skills,
                programmingLanguages: updatedProg,
              },
            };
          } else if (sec === 'projects') {
            const updatedProj = [...(prev.projects || [])];
            if (updatedProj.length > 0) {
              const p = { ...updatedProj[0] };
              const addTech = ctx || skillKeyword;
              p.technologies = p.technologies ? `${p.technologies}, ${addTech}` : addTech;
              if (ctx) {
                p.description = p.description
                  ? `${p.description}\n• Applied ${ctx} to enhance system performance and maintainability.`
                  : `• Applied ${ctx} to enhance system performance and maintainability.`;
              }
              updatedProj[0] = p;
            }
            return { ...prev, projects: updatedProj };
          } else if (sec === 'education') {
            const updatedEdu = [...(prev.education || [])];
            if (updatedEdu.length > 0) {
              const e = { ...updatedEdu[0] };
              if (ctx) {
                e.description = e.description
                  ? `${e.description} Coursework & specialization: ${ctx}.`
                  : `Specialization: ${ctx}.`;
              }
              updatedEdu[0] = e;
            }
            return { ...prev, education: updatedEdu };
          }
          return prev;
        });
      }

      setSummaryGenProgress(18);
      await new Promise((r) => setTimeout(r, 120));
      setSummaryGenProgress(35);
      await new Promise((r) => setTimeout(r, 180));

      // ── STAGE 2: Rephrase Content & Draft Tailored Summary ──
      setSummaryGenStep(2);
      setSummaryGenProgress(40);
      const targetRoleTitle = job?.title || candidateHeadline || 'Software Engineer';
      setSummaryGenStageText('Analyzing resume content for next section...');

      const targetCompany = job?.company || 'Target Organization';
      const targetSkills =
        (job?.skills || []).join(', ') || 'modern software development, REST APIs, problem solving';

      const prompt = `You are TalentPilot Copilot, an expert AI ATS resume optimizer.
Analyze this candidate's actual resume profile against the target job role and produce tailored optimizations.

CANDIDATE ACTUAL PROFILE:
- Name: ${candidateName}
- Headline: ${candidateHeadline}
- Current Summary: ${currentResume.summary || 'None'}
- Technical Skills: ${allCandidateSkills || 'Not listed'}
- Work Experience: ${candidateExperience || 'None listed'}
- Key Projects: ${candidateProjects || 'None listed'}
- Education: ${candidateEducation || 'None listed'}
${options?.context ? `- Candidate Input Context: ${options.context}` : ''}

TARGET JOB ROLE:
- Role: ${targetRoleTitle}
- Company: ${targetCompany}
- Required Skills: ${targetSkills}
${job?.description ? `- Job Excerpt: ${job.description.slice(0, 300)}` : ''}

INSTRUCTIONS:
1. Write a tailored, high-impact ATS professional summary (3-4 sentences, approx 50-70 words) for THIS specific candidate. Mention their actual background, key technical strengths that align with ${targetRoleTitle}, practical project/work highlights, and education. Do NOT fabricate unrelated degrees or titles.
2. Provide 2-3 specific suggested actions / content rephrasings for their projects, experience, or skills to boost keyword alignment and ATS score.

Return ONLY a valid JSON object in this format (no markdown fences, no conversational text):
{
  "summary": "...",
  "suggestedActions": [
    {
      "id": "action-1",
      "title": "Short title of suggested rephrase",
      "section": "Projects",
      "category": "Impact Rephrase",
      "existingText": "Original text snippet",
      "newText": "Optimized version with target keywords and action verbs",
      "bulletItems": ["bullet 1", "bullet 2"]
    }
  ]
}`;

      let aiSummary = '';
      let aiActions: Array<any> = [];

      try {
        const progressTimer = setInterval(() => {
          setSummaryGenProgress((p) => (p < 78 ? p + 8 : p));
        }, 160);

        const responsePromise = sendCopilotMessage(prompt, {
          role: 'candidate',
          resumeId: id || '',
          jobId: job?.id || '',
        });

        // Fast timeout so UI never hangs while allowing responsive copilot answer
        const timeoutPromise = new Promise<{ success: boolean; message: string }>((_, reject) =>
          setTimeout(() => reject(new Error('AI response timeout')), 1800)
        );

        const response = await Promise.race([responsePromise, timeoutPromise]);
        clearInterval(progressTimer);

        if (response.success && response.message) {
          try {
            let cleaned = response.message.trim();
            if (cleaned.startsWith('```json')) cleaned = cleaned.replace(/^```json/, '').replace(/```$/, '').trim();
            else if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```/, '').replace(/```$/, '').trim();

            const parsed = JSON.parse(cleaned);
            if (parsed.summary && typeof parsed.summary === 'string') {
              aiSummary = parsed.summary.trim();
            }
            if (Array.isArray(parsed.suggestedActions) && parsed.suggestedActions.length > 0) {
              aiActions = parsed.suggestedActions;
            }
          } catch (jsonErr) {
            console.warn('AI returned non-JSON text, extracting plain summary text:', jsonErr);
            if (response.message.length > 30) {
              aiSummary = response.message.replace(/[{}[\]"]/g, '').trim();
            }
          }
        }
      } catch (aiErr) {
        console.warn('AI copilot call fallback engaged:', aiErr);
      }

      setSummaryGenProgress(80);

      // ── Intelligent Profile Synthesizer Fallback (Personalized from candidate's actual profile) ──
      if (!aiSummary) {
        const topSkills =
          allCandidateSkills
            .split(',')
            .map((s) => s.trim())
            .filter(Boolean)
            .slice(0, 4)
            .join(', ') || 'Software Engineering and Modern Development';
        const firstProject = currentResume.projects?.[0]?.title || 'web applications';
        const eduBrief = currentResume.education?.[0]
          ? `${currentResume.education[0].degree || 'Degree'} from ${currentResume.education[0].institution || 'University'}${currentResume.education[0].cgpa ? ` with a CGPA of ${currentResume.education[0].cgpa}` : ''}`
          : 'a solid academic foundation in Computer Science';

        aiSummary = `${candidateHeadline} with practical expertise in ${topSkills}, dedicated to engineering reliable, database-driven applications aligned with the ${targetRoleTitle} position at ${targetCompany}. Experienced in contributing to ${firstProject}, developing responsive interfaces, and integrating RESTful APIs. Currently pursuing ${eduBrief}, with a passion for building scalable solutions and quickly adopting emerging technologies.`;
      }

      if (!aiActions || aiActions.length === 0) {
        const primaryProject = currentResume.projects?.[0];
        const projTitle = primaryProject ? primaryProject.title : 'Primary Project';
        aiActions = [
          {
            id: `rephrase-proj-${Date.now()}`,
            title: `Optimized project impact for ${projTitle}`,
            section: 'Projects',
            category: 'Impact Rephrase',
            existingText:
              primaryProject?.description?.slice(0, 100) || 'Developed responsive full-stack features.',
            newText: `Architected and deployed scalable features using ${job?.skills?.slice(0, 3).join(', ') || 'modern APIs'}, improving response times and user engagement.`,
            bulletItems: [
              `Engineered core services for ${projTitle} leveraging ${job?.skills?.slice(0, 2).join(' & ') || 'REST APIs and database indexing'}.`,
              `Enhanced system reliability and throughput with automated validation and responsive client-side state management.`,
              `Aligned architectural components with production deployment and cloud standards.`,
            ],
          },
          {
            id: `align-skills-${Date.now()}`,
            title: `Emphasized ${job?.skills?.[0] || 'Core Domain'} keyword alignment`,
            section: 'Skills',
            category: 'Keyword Match',
            existingText: 'Technical skills inventory',
            newText: `Highlighted ${targetSkills} across primary technical competencies.`,
            bulletItems: [
              `Prioritized ${job?.skills?.slice(0, 4).join(', ') || 'key requirements'} in technical competencies section.`,
              `Enhanced keyword density to pass automated ATS screening filters with high relevancy.`,
            ],
          },
        ];
      }

      // ── STAGE 3: Finalizing Updates & Applying to Resume ──
      setSummaryGenStep(3);
      setSummaryGenProgress(90);
      setSummaryGenStageText('Preparing optimization recommendations...');

      setAiTailoredSummary(aiSummary);
      setEditableTailoredSummary(aiSummary);
      setDynamicSuggestedActions(aiActions);

      // Save summary into candidate resume
      handleUpdate((prev) => ({
        ...prev,
        summary: aiSummary,
      }));

      await new Promise((r) => setTimeout(r, 200));
      setSummaryGenProgress(100);
      await new Promise((r) => setTimeout(r, 350));

      showToast({
        type: 'success',
        title: 'Keywords Incorporated! 🎉',
        message: 'AI analyzed your profile and prepared tailored content for rephrasing.',
      });

      setIsGeneratingSummary(false);
      setAiWizardStep(options?.targetStep || 2);
    } catch (err: any) {
      console.error('Error during profile analysis and summary generation:', err);
      showToast({
        type: 'error',
        title: 'Analysis Error',
        message: err?.message || 'Could not complete background analysis. Please try again.',
      });
      setIsGeneratingSummary(false);
    }
  };

  const handleAcceptSuggestedChange = (actionId: string) => {
    if (actionId === 'skills-cs') {
      handleUpdate((prev) => {
        const currentProg = prev.skills?.programmingLanguages || 'Java, JavaScript, C, HTML, CSS';
        const updatedProg = currentProg.includes('Computer Science')
          ? currentProg
          : `${currentProg}, Computer Science, related field of study`;
        return {
          ...prev,
          skills: {
            ...prev.skills,
            programmingLanguages: updatedProg,
          },
        };
      });
      setWizardFixedActionIds((prev) => new Set(prev).add('skills-cs'));
      showToast({
        type: 'success',
        title: 'Skills Updated',
        message: 'Added Computer Science & related field of study keywords.',
      });
    } else if (actionId === 'edu-degree') {
      handleUpdate((prev) => {
        const updatedEdu = [...(prev.education || [])];
        if (updatedEdu.length > 0) {
          updatedEdu[0] = {
            ...updatedEdu[0],
            degree: updatedEdu[0].degree || 'B.Tech in Computer Science and Engineering',
            fieldOfStudy: updatedEdu[0].fieldOfStudy || 'Computer Science and Engineering',
            description: updatedEdu[0].description
              ? `${updatedEdu[0].description} • Bachelor's level coursework in core CS fundamentals.`
              : "Bachelor's level degree in Computer Science or related field of study. Coursework in Data Structures, Algorithms, OOP, DBMS, Computer Networks.",
          };
        }
        return { ...prev, education: updatedEdu };
      });
      setWizardFixedActionIds((prev) => new Set(prev).add('edu-degree'));
      showToast({
        type: 'success',
        title: 'Education Updated',
        message: "Added Bachelor's level degree qualification.",
      });
    } else if (actionId === 'cert-tech') {
      handleUpdate((prev) => {
        const updatedCerts = [...(prev.certifications || [])];
        const exists = updatedCerts.some((c) =>
          c.title.toLowerCase().includes('technical certification')
        );
        if (!exists) {
          updatedCerts.push({
            id: `cert-${Date.now()}`,
            title: selectedJob
              ? `${selectedJob.title} Technical Certification`
              : 'Technical Certification',
            issuer: 'Industry Certification Body',
            issueDate: new Date().getFullYear().toString(),
            description:
              'Demonstrated proficiency in core technical domains and software standards.',
          });
        }
        return { ...prev, certifications: updatedCerts };
      });
      setWizardFixedActionIds((prev) => new Set(prev).add('cert-tech'));
      showToast({
        type: 'success',
        title: 'Certification Added! 🎉',
        message: 'Technical Certification added to your resume.',
      });
    } else {
      // Dynamic suggested action
      const matchedAction = dynamicSuggestedActions.find((a) => a.id === actionId);
      if (matchedAction) {
        handleUpdate((prev) => {
          if (matchedAction.section === 'Projects' && prev.projects && prev.projects.length > 0) {
            const updatedProj = [...prev.projects];
            const p = { ...updatedProj[0] };
            if (matchedAction.bulletItems && matchedAction.bulletItems.length > 0) {
              p.description = matchedAction.bulletItems.map((b) => `• ${b}`).join('\n');
            } else if (matchedAction.newText) {
              p.description = matchedAction.newText;
            }
            updatedProj[0] = p;
            return { ...prev, projects: updatedProj };
          } else if (
            matchedAction.section === 'Experience' &&
            prev.experience &&
            prev.experience.length > 0
          ) {
            const updatedExp = [...prev.experience];
            const e = { ...updatedExp[0] };
            if (matchedAction.bulletItems && matchedAction.bulletItems.length > 0) {
              e.description = matchedAction.bulletItems.map((b) => `• ${b}`).join('\n');
            } else if (matchedAction.newText) {
              e.description = matchedAction.newText;
            }
            updatedExp[0] = e;
            return { ...prev, experience: updatedExp };
          } else if (matchedAction.section === 'Skills' && prev.skills) {
            const currentProg = prev.skills.programmingLanguages || '';
            const addWord = selectedJob?.skills?.[0] || 'Cloud & Distributed Systems';
            const updatedProg = currentProg.includes(addWord)
              ? currentProg
              : currentProg
                ? `${currentProg}, ${addWord}`
                : addWord;
            return {
              ...prev,
              skills: {
                ...prev.skills,
                programmingLanguages: updatedProg,
              },
            };
          }
          return prev;
        });
        setWizardFixedActionIds((prev) => new Set(prev).add(actionId));
        showToast({
          type: 'success',
          title: 'Changes Applied! 🪄',
          message: `${matchedAction.title} applied to your resume.`,
        });
      }
    }
    setActiveSuggestedChange(null);
  };

